var SITUATIES = [{"n": 1, "t": "Kennismaken", "tt": {"de": "Sich kennenlernen", "nl": "Kennismaken", "en": "Getting to know each other", "fr": "Faire connaissance", "es": "Conocerse"}, "r": [["j", "Hallo, ich heiße Anna.", "Hallo, ik heet Anna.", "Hi, my name is Anna.", "Bonjour, je m'appelle Anna.", "Hola, me llamo Anna."], ["a", "Hallo Anna, ich bin Tom. Schön, dich kennenzulernen.", "Hallo Anna, ik ben Tom. Leuk je te ontmoeten.", "Hi Anna, I'm Tom. Nice to meet you.", "Salut Anna, je suis Tom. Enchanté.", "Hola Anna, soy Tom. Encantado de conocerte."], ["j", "Freut mich auch. Woher kommst du?", "Leuk je ook te ontmoeten. Waar kom je vandaan?", "Nice to meet you too. Where are you from?", "Moi aussi. Tu viens d'où ?", "Igualmente. ¿De dónde eres?"], ["a", "Ich komme aus Utrecht. Und du?", "Ik kom uit Utrecht. En jij?", "I'm from Utrecht. And you?", "Je viens d'Utrecht. Et toi ?", "Vengo de Utrecht. ¿Y tú?"], ["j", "Ich komme aus Groningen.", "Ik kom uit Groningen.", "I'm from Groningen.", "Je viens de Groningue.", "Yo vengo de Groninga."], ["a", "Wohnst du hier schon lange?", "Woon je hier al lang?", "Have you lived here long?", "Tu habites ici depuis longtemps ?", "¿Vives aquí desde hace mucho?"], ["j", "Nein, erst seit drei Monaten.", "Nee, pas drie maanden.", "No, only for three months.", "Non, depuis seulement trois mois.", "No, solo desde hace tres meses."], ["a", "Was machst du hier?", "Wat doe je hier?", "What do you do here?", "Qu'est-ce que tu fais ici ?", "¿A qué te dedicas aquí?"], ["j", "Ich mache eine Ausbildung in der Sozialen Arbeit.", "Ik volg een opleiding in de zorg.", "I'm doing a training in social care.", "Je fais une formation dans le social.", "Estoy haciendo una formación en atención social."], ["a", "Oh, das ist interessant. Wie lange dauert das?", "Oh, dat is interessant. Hoe lang duurt dat?", "Oh, that's interesting. How long does it take?", "Oh, c'est intéressant. Ça dure combien de temps ?", "Qué interesante. ¿Cuánto tiempo dura?"], ["j", "Noch ein Jahr.", "Nog een jaar.", "Another year.", "Encore un an.", "Un año más."], ["a", "Gut gemacht! Und hast du Hobbys?", "Goed bezig! Heb je hobby's?", "Well done! Do you have any hobbies?", "Bien joué ! Tu as des loisirs ?", "¡Muy bien! ¿Tienes aficiones?"], ["j", "Ja, ich mache gern Musik.", "Ja, ik maak graag muziek.", "Yes, I like making music.", "Oui, j'aime faire de la musique.", "Sí, me gusta hacer música."], ["a", "Cool. Welche Musik machst du?", "Cool. Wat voor muziek maak je?", "Cool. What kind of music do you make?", "Cool. Tu fais quel genre de musique ?", "Genial. ¿Qué tipo de música haces?"], ["j", "Ich mache Beats und Songs am Computer.", "Ik maak beats en liedjes op de computer.", "I make beats and songs on my computer.", "Je fais des beats et des chansons sur l'ordinateur.", "Hago beats y canciones en el ordenador."], ["a", "Super! Vielleicht hören wir mal etwas zusammen.", "Super! Misschien luisteren we samen eens iets.", "Great! Maybe we can listen to something together sometime.", "Super ! On pourra peut-être écouter quelque chose ensemble.", "¡Genial! Quizás algún día escuchamos algo juntos."]]}, {"n": 2, "t": "Begroeten en afscheid nemen", "tt": {"de": "Begrüßen und verabschieden", "nl": "Begroeten en afscheid nemen", "en": "Saying hello and goodbye", "fr": "Dire bonjour et au revoir", "es": "Saludar y despedirse"}, "r": [["j", "Guten Morgen! Wie geht es Ihnen?", "Goedemorgen! Hoe gaat het?", "Good morning! How are you?", "Bonjour ! Comment allez-vous ?", "¡Buenos días! ¿Cómo está usted?"], ["a", "Danke, gut. Und Ihnen?", "Dank je, goed. En met jou?", "Thanks, good. And you?", "Merci, bien. Et vous ?", "Bien, gracias. ¿Y usted?"], ["j", "Auch gut, danke.", "Ook goed, dank je.", "Good too, thanks.", "Très bien, merci.", "Muy bien, gracias."], ["a", "Schön, Sie zu sehen.", "Fijn je te zien.", "Good to see you.", "Ravi de vous voir.", "Qué bueno verle."], ["j", "Ihnen auch. Bis später!", "Jou ook. Tot later!", "You too. See you later!", "Pareillement. À plus tard !", "Igualmente. ¡Hasta luego!"], ["a", "Ja, bis später. Viel Spaß heute!", "Ja, tot later. Veel plezier vandaag!", "Yes, see you later. Have fun today!", "Oui, à plus tard. Bonne journée !", "Sí, hasta luego. ¡Que lo pases bien hoy!"], ["j", "Danke, dir auch. Tschüss!", "Dank je, jij ook. Doei!", "Thanks, you too. Bye!", "Merci, toi aussi. Salut !", "Gracias, igualmente. ¡Adiós!"], ["a", "Tschüss! Bis bald.", "Doei! Tot snel.", "Bye! See you soon.", "Salut ! À bientôt.", "¡Adiós! Hasta pronto."], ["j", "Entschuldigung, ich muss gehen.", "Sorry, ik moet gaan.", "Sorry, I have to go.", "Désolé, je dois y aller.", "Perdón, tengo que irme."], ["a", "Kein Problem. Gute Reise!", "Geen probleem. Goede reis!", "No problem. Have a good trip!", "Pas de problème. Bon voyage !", "No hay problema. ¡Buen viaje!"], ["j", "Danke! Auf Wiedersehen.", "Dank je! Tot ziens.", "Thank you! Goodbye.", "Merci ! Au revoir.", "¡Gracias! Hasta la vista."], ["a", "Auf Wiedersehen!", "Tot ziens!", "Goodbye!", "Au revoir !", "¡Hasta la vista!"], ["j", "Wie spät ist es eigentlich?", "Hoe laat is het eigenlijk?", "What time is it, by the way?", "Quelle heure est-il, au fait ?", "¿Qué hora es, por cierto?"], ["a", "Es ist kurz nach zehn.", "Het is net na tienen.", "It's just after ten.", "Il est dix heures passées.", "Son las diez y pico."], ["j", "Oh, dann muss ich wirklich los.", "O, dan moet ik echt gaan.", "Oh, then I really have to go.", "Oh, alors je dois vraiment partir.", "Vaya, entonces de verdad tengo que irme."], ["a", "Dann bis morgen!", "Dan tot morgen!", "Then see you tomorrow!", "Alors à demain !", "¡Entonces hasta mañana!"], ["j", "Bis morgen! Schlaf gut.", "Tot morgen! Slaap lekker.", "See you tomorrow! Sleep well.", "À demain ! Bonne nuit.", "¡Hasta mañana! Que descanses."]]}, {"n": 3, "t": "Station: kaartje kopen en perron vinden", "tt": {"de": "Bahnhof: Fahrkarte kaufen und Gleis finden", "nl": "Station: kaartje kopen en perron vinden", "en": "Station: buying a ticket and finding the platform", "fr": "Gare : acheter un billet et trouver le quai", "es": "Estación: comprar un billete y encontrar el andén"}, "r": [["j", "Entschuldigung, wo kann ich ein Ticket kaufen?", "Excuseer, waar kan ik een kaartje kopen?", "Excuse me, where can I buy a ticket?", "Excusez-moi, où puis-je acheter un billet ?", "Perdone, ¿dónde puedo comprar un billete?"], ["a", "Am Automaten dort drüben oder am Schalter.", "Bij de automaat daar of aan het loket.", "At the machine over there or at the counter.", "Au distributeur là-bas ou au guichet.", "En la máquina de allí o en la taquilla."], ["j", "Ein Ticket nach Amsterdam, bitte.", "Een kaartje naar Amsterdam, alstublieft.", "One ticket to Amsterdam, please.", "Un billet pour Amsterdam, s'il vous plaît.", "Un billete a Ámsterdam, por favor."], ["a", "Einfach oder hin und zurück?", "Enkele reis of retour?", "Single or return?", "Aller simple ou aller-retour ?", "¿Solo ida o ida y vuelta?"], ["j", "Hin und zurück, bitte.", "Retour, alstublieft.", "Return, please.", "Aller-retour, s'il vous plaît.", "Ida y vuelta, por favor."], ["a", "Das macht zwölf Euro fünfzig.", "Dat is twaalf euro vijftig.", "That's twelve euros fifty.", "Ça fait douze euros cinquante.", "Son doce euros con cincuenta."], ["j", "Kann ich mit Karte bezahlen?", "Kan ik met pin betalen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, natürlich. Der Automat akzeptiert Karten.", "Ja, natuurlijk. De automaat neemt pinpassen aan.", "Yes, of course. The machine accepts cards.", "Oui, bien sûr. Le distributeur accepte les cartes.", "Sí, claro. La máquina acepta tarjetas."], ["j", "Auf welchem Gleis fährt der Zug?", "Van welk spoor vertrekt de trein?", "Which platform does the train leave from?", "Quel quai pour le train ?", "¿De qué andén sale el tren?"], ["a", "Gleis drei, auf der anderen Seite.", "Spoor drie, aan de andere kant.", "Platform three, on the other side.", "Quai trois, de l'autre côté.", "Andén tres, al otro lado."], ["j", "Muss ich über die Brücke gehen?", "Moet ik over de brug lopen?", "Do I have to go over the bridge?", "Il faut passer par le pont ?", "¿Tengo que cruzar el puente?"], ["a", "Ja, über die Treppe oder den Aufzug.", "Ja, via de trap of de lift.", "Yes, by the stairs or the lift.", "Oui, par les escaliers ou l'ascenseur.", "Sí, por las escaleras o el ascensor."], ["j", "Gibt es hier einen Aufzug?", "Is er hier een lift?", "Is there a lift here?", "Il y a un ascenseur ici ?", "¿Hay un ascensor aquí?"], ["a", "Ja, am Ende des Bahnsteigs.", "Ja, aan het eind van het perron.", "Yes, at the end of the platform.", "Oui, au bout du quai.", "Sí, al final del andén."], ["j", "Danke. Ist der Zug pünktlich?", "Dank je. Rijdt de trein op tijd?", "Thanks. Is the train on time?", "Merci. Le train est à l'heure ?", "Gracias. ¿El tren llega a tiempo?"], ["a", "Ja, er fährt in fünf Minuten.", "Ja, hij vertrekt over vijf minuten.", "Yes, it leaves in five minutes.", "Oui, il part dans cinq minutes.", "Sí, sale en cinco minutos."], ["j", "Super, danke für die Hilfe!", "Super, bedankt voor de hulp!", "Great, thanks for the help!", "Super, merci pour votre aide !", "¡Genial, gracias por la ayuda!"], ["a", "Gern geschehen. Gute Fahrt!", "Graag gedaan. Goede reis!", "You're welcome. Have a good journey!", "Avec plaisir. Bon voyage !", "De nada. ¡Buen viaje!"]]}, {"n": 4, "t": "Trein en bus: plaats, instappen en vertraging", "tt": {"de": "Zug und Bus: Platz, Einsteigen und Verspätung", "nl": "Trein en bus: plaats, instappen en vertraging", "en": "Train and bus: seats, getting on and delays", "fr": "Train et bus : place, montée et retard", "es": "Tren y autobús: asiento, subir y retraso"}, "r": [["j", "Ist hier noch frei?", "Is deze plaats nog vrij?", "Is this seat free?", "Cette place est libre ?", "¿Está libre este asiento?"], ["a", "Ja, bitte setzen Sie sich.", "Ja, ga zitten.", "Yes, please sit down.", "Oui, asseyez-vous.", "Sí, siéntese, por favor."], ["j", "Danke. Fährt dieser Zug nach Den Haag?", "Dank je. Gaat deze trein naar Den Haag?", "Thanks. Does this train go to The Hague?", "Merci. Ce train va à La Haye ?", "Gracias. ¿Este tren va a La Haya?"], ["a", "Nein, der nächste Zug fährt in zehn Minuten.", "Nee, de volgende trein gaat over tien minuten.", "No, the next train leaves in ten minutes.", "Non, le prochain train part dans dix minutes.", "No, el próximo tren sale en diez minutos."], ["j", "Okay. Wo muss ich umsteigen?", "Oké. Waar moet ik overstappen?", "Okay. Where do I change?", "D'accord. Où dois-je changer ?", "Vale. ¿Dónde tengo que cambiar?"], ["a", "In Utrecht Centraal.", "In Utrecht Centraal.", "At Utrecht Centraal.", "À Utrecht Centraal.", "En Utrecht Centraal."], ["j", "Ist der Zug heute verspätet?", "Heeft de trein vertraging vandaag?", "Is the train delayed today?", "Le train a du retard aujourd'hui ?", "¿El tren va con retraso hoy?"], ["a", "Ja, etwa zwanzig Minuten.", "Ja, ongeveer twintig minuten.", "Yes, about twenty minutes.", "Oui, environ vingt minutes.", "Sí, unos veinte minutos."], ["j", "Kann ich mit diesem Ticket auch den Bus nehmen?", "Kan ik met dit kaartje ook de bus nemen?", "Can I also take the bus with this ticket?", "Puis-je prendre le bus avec ce billet ?", "¿Puedo tomar el autobús con este billete?"], ["a", "Ja, im Zug und im Bus gilt dasselbe Ticket.", "Ja, dit kaartje geldt in de trein en in de bus.", "Yes, the same ticket works on the train and the bus.", "Oui, le même billet vaut pour le train et le bus.", "Sí, el mismo billete vale para el tren y el autobús."], ["j", "Halte ich hier für das Zentrum?", "Stop ik hier voor het centrum?", "Do I get off here for the centre?", "Je descends ici pour le centre ?", "¿Me bajo aquí para el centro?"], ["a", "Nein, zwei Haltestellen weiter.", "Nee, twee haltes verder.", "No, two stops further.", "Non, deux arrêts plus loin.", "No, dos paradas más allá."], ["j", "Sagen Sie mir bitte Bescheid?", "Kunt u mij waarschuwen als we er zijn?", "Could you let me know when we get there?", "Vous pouvez me prévenir ?", "¿Me avisa, por favor?"], ["a", "Natürlich, ich sage Ihnen Bescheid.", "Natuurlijk, ik zeg het je.", "Of course, I'll tell you.", "Bien sûr, je vous préviens.", "Claro, le aviso."], ["j", "Entschuldigung, ist das der Bus nach Zentrum?", "Sorry, is dit de bus naar het centrum?", "Sorry, is this the bus to the centre?", "Pardon, c'est le bus pour le centre ?", "Perdone, ¿este autobús va al centro?"], ["a", "Ja, steigen Sie hinten ein.", "Ja, stap achteraan in.", "Yes, get on at the back.", "Oui, montez par l'arrière.", "Sí, suba por atrás."], ["j", "Danke! Ich steige an der nächsten Haltestelle aus.", "Dank je! Ik stap uit bij de volgende halte.", "Thanks! I'll get off at the next stop.", "Merci ! Je descends au prochain arrêt.", "¡Gracias! Me bajo en la próxima parada."]]}, {"n": 5, "t": "De weg vragen", "tt": {"de": "Nach dem Weg fragen", "nl": "De weg vragen", "en": "Asking the way", "fr": "Demander son chemin", "es": "Preguntar el camino"}, "r": [["j", "Entschuldigung, wo ist der Bahnhof?", "Excuseer, waar is het station?", "Excuse me, where is the train station?", "Excusez-moi, où est la gare ?", "Perdone, ¿dónde está la estación?"], ["a", "Gehen Sie geradeaus und dann links.", "Loop rechtdoor en dan linksaf.", "Go straight and then turn left.", "Allez tout droit, puis tournez à gauche.", "Siga recto y luego gire a la izquierda."], ["j", "Wie weit ist das zu Fuß?", "Hoe ver is het lopend?", "How far is it on foot?", "C'est loin à pied ?", "¿A qué distancia está a pie?"], ["a", "Etwa zehn Minuten.", "Ongeveer tien minuten.", "About ten minutes.", "Environ dix minutes.", "Unos diez minutos."], ["j", "Muss ich über eine Ampel?", "Moet ik bij een stoplicht oversteken?", "Do I have to cross at a traffic light?", "Il faut traverser à un feu ?", "¿Tengo que cruzar en un semáforo?"], ["a", "Ja, an der zweiten Ampel rechts.", "Ja, bij het tweede stoplicht rechtsaf.", "Yes, turn right at the second traffic light.", "Oui, au deuxième feu, à droite.", "Sí, en el segundo semáforo gire a la derecha."], ["j", "Ist das die Hauptstraße?", "Is dit de hoofdstraat?", "Is this the main street?", "C'est la rue principale ?", "¿Es esta la calle principal?"], ["a", "Nein, das ist eine kleine Seitenstraße.", "Nee, dit is een zijstraatje.", "No, it's a small side street.", "Non, c'est une petite rue latérale.", "No, es una calle lateral pequeña."], ["j", "Kann ich das auf der Karte sehen?", "Kan ik dat even op de kaart zien?", "Can I see that on the map?", "Je peux voir ça sur la carte ?", "¿Puedo verlo en el mapa?"], ["a", "Natürlich. Hier, das ist die Straße.", "Natuurlijk. Hier, dit is de straat.", "Of course. Here, this is the street.", "Bien sûr. Voilà, c'est la rue.", "Claro. Aquí está la calle."], ["j", "Ach so, jetzt verstehe ich.", "Ah, nu snap ik het.", "Oh, now I understand.", "Ah, je comprends maintenant.", "Ah, ahora lo entiendo."], ["a", "Gut. Haben Sie noch Fragen?", "Goed. Heb je nog vragen?", "Good. Do you have more questions?", "Bien. Vous avez encore des questions ?", "Bien. ¿Tiene más preguntas?"], ["j", "Nein, danke. Gibt es hier in der Nähe eine Apotheke?", "Nee, dank je. Is er hier in de buurt een apotheek?", "No, thanks. Is there a pharmacy nearby?", "Non, merci. Il y a une pharmacie près d'ici ?", "No, gracias. ¿Hay una farmacia cerca?"], ["a", "Ja, gleich um die Ecke.", "Ja, meteen om de hoek.", "Yes, just around the corner.", "Oui, juste au coin de la rue.", "Sí, a la vuelta de la esquina."], ["j", "Perfekt. Vielen Dank für Ihre Hilfe!", "Perfect. Bedankt voor je hulp!", "Perfect. Thank you for your help!", "Parfait. Merci pour votre aide !", "¡Perfecto! ¡Gracias por su ayuda!"], ["a", "Gern geschehen. Schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]]}, {"n": 6, "t": "Taxi: rit regelen en betalen", "tt": {"de": "Taxi: Fahrt vereinbaren und bezahlen", "nl": "Taxi: rit regelen en betalen", "en": "Taxi: arranging the ride and paying", "fr": "Taxi : organiser la course et payer", "es": "Taxi: pedir el viaje y pagar"}, "r": [["j", "Ein Taxi, bitte.", "Een taxi, alstublieft.", "A taxi, please.", "Un taxi, s'il vous plaît.", "Un taxi, por favor."], ["a", "Wohin möchten Sie fahren?", "Waar wilt u naartoe?", "Where would you like to go?", "Où voulez-vous aller ?", "¿A dónde quiere ir?"], ["j", "Zum Hauptbahnhof, bitte.", "Naar het centraal station, alstublieft.", "To the central station, please.", "À la gare centrale, s'il vous plaît.", "A la estación central, por favor."], ["a", "Steigen Sie ein. Das dauert etwa zehn Minuten.", "Stap maar in. Het duurt ongeveer tien minuten.", "Get in. It takes about ten minutes.", "Montez. Ça prend environ dix minutes.", "Suba. Tarda unos diez minutos."], ["j", "Können Sie bitte langsamer fahren?", "Kunt u iets langzamer rijden?", "Could you drive a bit slower, please?", "Vous pouvez rouler un peu moins vite ?", "¿Puede conducir un poco más despacio, por favor?"], ["a", "Natürlich. Ist es so in Ordnung?", "Natuurlijk. Is dit goed?", "Of course. Is this okay?", "Bien sûr. Ça vous va ?", "Claro. ¿Así está bien?"], ["j", "Ja, danke. Halten Sie bitte hier an!", "Ja, dank je. Stop hier alstublieft!", "Yes, thanks. Please stop here!", "Oui, merci. Arrêtez-vous ici, s'il vous plaît !", "Sí, gracias. ¡Pare aquí, por favor!"], ["a", "Das macht sechzehn Euro.", "Dat is zestien euro.", "That's sixteen euros.", "Ça fait seize euros.", "Son dieciséis euros."], ["j", "Kann ich mit Karte zahlen?", "Kan ik met pin betalen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, halten Sie das Gerät bitte hier.", "Ja, houd uw pas hier even vast.", "Yes, please hold the card here.", "Oui, approchez la carte ici, s'il vous plaît.", "Sí, acerque la tarjeta aquí, por favor."], ["j", "Hier ist die Quittung. Ich brauche eine Quittung.", "Hier is het bonnetje. Kan ik een bon krijgen?", "Here you go. I'd like a receipt.", "Voilà. Je voudrais un reçu, s'il vous plaît.", "Aquí tiene. Necesito un recibo."], ["a", "Hier bitte. Schönen Tag noch!", "Alstublieft. Fijne dag nog!", "Here you are. Have a nice day!", "Voilà. Bonne journée !", "Aquí tiene. ¡Que tenga buen día!"], ["j", "Danke, Ihnen auch!", "Dank u, u ook!", "Thanks, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"], ["a", "Wiedersehen!", "Tot ziens!", "Goodbye!", "Au revoir !", "¡Hasta luego!"], ["j", "Entschuldigung, ich habe meine Tasche im Taxi vergessen.", "Sorry, ik ben mijn tas vergeten in de taxi.", "Sorry, I left my bag in the taxi.", "Excusez-moi, j'ai oublié mon sac dans le taxi.", "Perdone, me he dejado la bolsa en el taxi."], ["a", "Oh, ich schaue nach. Warten Sie kurz.", "Oh, ik kijk even. Wacht even.", "Oh, let me check. Wait a moment.", "Oh, je regarde. Attendez un instant.", "Ah, miro. Espere un momento."], ["j", "Ist die Tasche schwarz mit einem Reißverschluss?", "Is de tas zwart met een ritssluiting?", "Is the bag black with a zip?", "Le sac est noir avec une fermeture éclair ?", "¿La bolsa es negra con cremallera?"], ["a", "Ja, hier ist sie. Gut, dass Sie sie nicht verloren haben.", "Ja, hier is hij. Gelukkig is hij niet kwijt.", "Yes, here it is. Good that you didn't lose it.", "Oui, la voilà. Heureusement, vous ne l'avez pas perdu.", "Sí, aquí está. Menos mal que no la perdió."], ["j", "Vielen Dank! Sie haben mir sehr geholfen.", "Heel erg bedankt! Je hebt me enorm geholpen.", "Thank you so much! You've been very helpful.", "Merci beaucoup ! Vous m'avez beaucoup aidé.", "¡Muchas gracias! Me ha ayudado mucho."]]}, {"n": 7, "t": "Café: iets bestellen", "tt": {"de": "Café: etwas bestellen", "nl": "Café: iets bestellen", "en": "Café: ordering something", "fr": "Café : commander quelque chose", "es": "Cafetería: pedir algo"}, "r": [["j", "Guten Tag, was kann ich bestellen?", "Hallo, wat kan ik bestellen?", "Hi, what can I order?", "Bonjour, qu'est-ce que je peux commander ?", "Hola, ¿qué puedo pedir?"], ["a", "Was möchten Sie trinken?", "Wat wilt u drinken?", "What would you like to drink?", "Qu'est-ce que vous voulez boire ?", "¿Qué le gustaría beber?"], ["j", "Einen Kaffee, bitte. Mit Milch.", "Een koffie, alstublieft. Met melk.", "A coffee, please. With milk.", "Un café, s'il vous plaît. Avec du lait.", "Un café, por favor. Con leche."], ["a", "Groß oder klein?", "Groot of klein?", "Large or small?", "Grand ou petit ?", "¿Grande o pequeño?"], ["j", "Klein, bitte.", "Klein, alstublieft.", "Small, please.", "Petit, s'il vous plaît.", "Pequeño, por favor."], ["a", "Möchten Sie noch etwas essen?", "Wilt u nog iets eten?", "Would you like anything to eat?", "Vous voulez manger quelque chose ?", "¿Quiere algo de comer?"], ["j", "Haben Sie Kuchen?", "Hebben jullie taart?", "Do you have cake?", "Vous avez des gâteaux ?", "¿Tienen tarta?"], ["a", "Ja, Apfelkuchen und Käsekuchen.", "Ja, appeltaart en cheesecake.", "Yes, apple cake and cheesecake.", "Oui, tarte aux pommes et cheesecake.", "Sí, tarta de manzana y tarta de queso."], ["j", "Ein Stück Apfelkuchen, bitte.", "Een stuk appeltaart, alstublieft.", "A slice of apple cake, please.", "Une part de tarte aux pommes, s'il vous plaît.", "Un trozo de tarta de manzana, por favor."], ["a", "Hier bitte. Möchten Sie hier essen oder mitnehmen?", "Alstublieft. Eet je hier of neem je het mee?", "Here you are. Eat here or take away?", "Voilà. Vous mangez sur place ou à emporter ?", "Aquí tiene. ¿Lo come aquí o para llevar?"], ["j", "Hier, bitte.", "Hier, alstublieft.", "Here, please.", "Ici, s'il vous plaît.", "Aquí, por favor."], ["a", "Gern. Das macht sieben Euro achtzig.", "Graag. Dat is zeven euro tachtig.", "Sure. That's seven euros eighty.", "Bien sûr. Ça fait sept euros quatre-vingts.", "Claro. Son siete euros con ochenta."], ["j", "Kann ich mit Karte bezahlen?", "Kan ik met pin betalen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, natürlich.", "Ja, natuurlijk.", "Yes, of course.", "Oui, bien sûr.", "Sí, claro."], ["j", "Gibt es hier WLAN? Wie ist das Passwort?", "Is er ook wifi hier? Wat is het wachtwoord?", "Is there wifi here? What's the password?", "Il y a le wifi ici ? Quel est le mot de passe ?", "¿Hay wifi aquí? ¿Cuál es la contraseña?"], ["a", "Ja, das Passwort steht auf dem Schild.", "Ja, het wachtwoord staat op het bordje.", "Yes, the password is on the sign.", "Oui, le mot de passe est sur la pancarte.", "Sí, la contraseña está en el cartel."], ["j", "Danke! Der Kuchen ist sehr lecker.", "Dank je! De taart is erg lekker.", "Thanks! The cake is delicious.", "Merci ! Le gâteau est délicieux.", "¡Gracias! La tarta está deliciosa."], ["a", "Das freut mich. Einen schönen Tag!", "Fijn dat het smaakt. Fijne dag!", "I'm glad you like it. Have a nice day!", "Ça me fait plaisir. Bonne journée !", "Me alegro. ¡Que tenga buen día!"]]}, {"n": 8, "t": "Restaurant: eten bestellen en rekening vragen", "tt": {"de": "Restaurant: Essen bestellen und um die Rechnung bitten", "nl": "Restaurant: eten bestellen en rekening vragen", "en": "Restaurant: ordering food and asking for the bill", "fr": "Restaurant : commander et demander l'addition", "es": "Restaurante: pedir la comida y la cuenta"}, "r": [["j", "Haben Sie noch einen Tisch für zwei Personen?", "Hebben jullie nog een tafel voor twee personen?", "Do you have a table for two left?", "Vous avez encore une table pour deux ?", "¿Tienen todavía una mesa para dos?"], ["a", "Ja, hier entlang, bitte.", "Ja, deze kant op, alstublieft.", "Yes, this way, please.", "Oui, par ici, s'il vous plaît.", "Sí, por aquí, por favor."], ["j", "Haben Sie eine Speisekarte?", "Heeft u een menukaart?", "Could we have the menu?", "Vous avez la carte, s'il vous plaît ?", "¿Tiene la carta, por favor?"], ["a", "Hier bitte. Möchten Sie schon etwas trinken?", "Alstublieft. Wilt u al iets drinken?", "Here you are. Would you like something to drink?", "Voilà. Vous voulez déjà boire quelque chose ?", "Aquí tiene. ¿Quiere beber algo ya?"], ["j", "Zwei Wasser und ein Glas Rotwein, bitte.", "Twee water en een glas rode wijn, alstublieft.", "Two waters and a glass of red wine, please.", "Deux eaux et un verre de vin rouge, s'il vous plaît.", "Dos aguas y una copa de vino tinto, por favor."], ["a", "Haben Sie schon entschieden?", "Hebt u al gekozen?", "Have you decided?", "Vous avez choisi ?", "¿Ya han decidido?"], ["j", "Ja, ich nehme das Gericht des Tages.", "Ja, ik neem het dagmenu.", "Yes, I'll have the dish of the day.", "Oui, je prends le plat du jour.", "Sí, yo tomo el plato del día."], ["a", "Und Sie?", "En u?", "And for you?", "Et pour vous ?", "¿Y usted?"], ["j", "Ich hätte gern die Suppe, und dann Fisch.", "Ik wil graag de soep, en daarna de vis.", "I'd like the soup, and then the fish.", "Je voudrais la soupe, puis le poisson.", "Quiero la sopa y luego el pescado."], ["a", "Ist alles in Ordnung mit dem Essen?", "Is alles naar wens?", "Is everything all right with the food?", "Tout est bon ?", "¿Todo bien con la comida?"], ["j", "Ja, sehr lecker, danke.", "Ja, heel lekker, dank je.", "Yes, very tasty, thanks.", "Oui, très bon, merci.", "Sí, muy rico, gracias."], ["a", "Möchten Sie noch etwas?", "Wilt u nog iets?", "Would you like anything else?", "Vous voulez autre chose ?", "¿Quiere algo más?"], ["j", "Die Rechnung, bitte.", "De rekening, alstublieft.", "The bill, please.", "L'addition, s'il vous plaît.", "La cuenta, por favor."], ["a", "Zusammen oder getrennt?", "Samen of apart?", "Together or separate?", "Ensemble ou séparé ?", "¿Juntos o por separado?"], ["j", "Getrennt, bitte.", "Apart, alstublieft.", "Separate, please.", "Séparément, s'il vous plaît.", "Por separado, por favor."], ["a", "Gern. Das macht zusammen vierzig Euro.", "Natuurlijk. Dat is samen veertig euro.", "Of course. That's forty euros in total.", "Bien sûr. Ça fait quarante euros en tout.", "Claro. Son cuarenta euros en total."], ["j", "Kann ich bar zahlen?", "Kan ik contant betalen?", "Can I pay in cash?", "Je peux payer en espèces ?", "¿Puedo pagar en efectivo?"], ["a", "Ja, klar. Hier ist das Wechselgeld.", "Ja, natuurlijk. Hier is het wisselgeld.", "Yes, sure. Here's your change.", "Oui, bien sûr. Voilà la monnaie.", "Sí, claro. Aquí tiene el cambio."], ["j", "Danke, das Essen war ausgezeichnet!", "Dank je, het eten was uitstekend!", "Thanks, the food was excellent!", "Merci, le repas était excellent !", "¡Gracias, la comida estaba excelente!"], ["a", "Freut mich! Auf Wiedersehen.", "Fijn! Tot ziens.", "Glad to hear it! Goodbye.", "Ravi ! Au revoir.", "¡Me alegro! Adiós."]]}, {"n": 9, "t": "Winkel: boodschappen en vragen naar producten", "tt": {"de": "Geschäft: Einkaufen und nach Produkten fragen", "nl": "Winkel: boodschappen en vragen naar producten", "en": "Shop: groceries and asking about products", "fr": "Magasin : courses et questions sur les produits", "es": "Tienda: la compra y preguntar por productos"}, "r": [["j", "Entschuldigung, wo finde ich Milch?", "Excuseer, waar vind ik melk?", "Excuse me, where can I find milk?", "Excusez-moi, où est le lait ?", "Perdone, ¿dónde encuentro leche?"], ["a", "Im hinteren Teil des Ladens, rechts.", "Achterin de winkel, rechts.", "At the back of the shop, on the right.", "Au fond du magasin, à droite.", "Al fondo de la tienda, a la derecha."], ["j", "Haben Sie auch laktosefreie Milch?", "Hebben jullie ook lactosevrije melk?", "Do you also have lactose-free milk?", "Vous avez aussi du lait sans lactose ?", "¿También tienen leche sin lactosa?"], ["a", "Ja, die Milch steht dort neben dem Joghurt.", "Ja, die staat daar naast de yoghurt.", "Yes, it's over there next to the yoghurt.", "Oui, il est là-bas à côté du yaourt.", "Sí, está allí al lado del yogur."], ["j", "Wie viel kostet das Brot?", "Hoeveel kost dit brood?", "How much is this bread?", "Combien coûte ce pain ?", "¿Cuánto cuesta este pan?"], ["a", "Das kostet 2,50 Euro.", "Dat kost twee euro vijftig.", "That's two euros fifty.", "Ça coûte deux euros cinquante.", "Cuesta dos euros con cincuenta."], ["j", "Haben Sie eine Tüte?", "Heeft u een tas?", "Do you have a bag?", "Vous avez un sac ?", "¿Tiene una bolsa?"], ["a", "Ja, eine Tüte kostet zehn Cent.", "Ja, een tas kost tien cent.", "Yes, a bag costs ten cents.", "Oui, un sac coûte dix centimes.", "Sí, una bolsa cuesta diez céntimos."], ["j", "Ist dieser Käse aus der Region?", "Komt deze kaas uit de streek?", "Is this cheese from the region?", "Ce fromage vient de la région ?", "¿Este queso es de la región?"], ["a", "Ja, der ist von einem Bauernhof hier in der Nähe.", "Ja, die komt van een boerderij hier in de buurt.", "Yes, it's from a farm near here.", "Oui, il vient d'une ferme près d'ici.", "Sí, viene de una granja cercana."], ["j", "Haben Sie das auch in einer kleineren Packung?", "Hebben jullie dit ook in een kleinere verpakking?", "Do you have this in a smaller pack?", "Vous avez ça en plus petit format ?", "¿Tienen esto en un envase más pequeño?"], ["a", "Ich schaue nach. Einen Moment, bitte.", "Ik kijk even. Eén moment.", "Let me check. One moment, please.", "Je regarde. Un instant, s'il vous plaît.", "Miro. Un momento, por favor."], ["j", "Danke. Wann machen Sie heute zu?", "Dank je. Hoe laat sluiten jullie vandaag?", "Thanks. When do you close today?", "Merci. Vous fermez à quelle heure aujourd'hui ?", "Gracias. ¿A qué hora cierran hoy?"], ["a", "Um zwanzig Uhr.", "Om acht uur.", "At eight o'clock.", "À vingt heures.", "A las ocho."], ["j", "Wo ist die Kasse?", "Waar is de kassa?", "Where is the checkout?", "Où est la caisse ?", "¿Dónde está la caja?"], ["a", "Vorne, neben dem Eingang.", "Vooraan, naast de ingang.", "At the front, next to the entrance.", "Devant, à côté de l'entrée.", "Al frente, junto a la entrada."], ["j", "Danke, schönen Tag noch!", "Dank je, fijne dag nog!", "Thanks, have a nice day!", "Merci, bonne journée !", "¡Gracias, que tenga buen día!"], ["a", "Danke, Ihnen auch!", "Dank je, jij ook!", "Thank you, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"]]}, {"n": 10, "t": "Betalen: pinnen, kassa en korting", "tt": {"de": "Bezahlen: Karte, Kasse und Rabatt", "nl": "Betalen: pinnen, kassa en korting", "en": "Paying: card, checkout and discounts", "fr": "Payer : carte, caisse et réduction", "es": "Pagar: tarjeta, caja y descuento"}, "r": [["j", "Ich möchte bezahlen.", "Ik wil betalen.", "I'd like to pay.", "Je voudrais payer.", "Quiero pagar."], ["a", "Das macht zusammen neun Euro dreißig.", "Dat is samen negen euro dertig.", "That's nine euros thirty together.", "Ça fait neuf euros trente en tout.", "Son nueve euros con treinta en total."], ["j", "Kann ich mit Karte zahlen?", "Kan ik pinnen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, halten Sie die Karte bitte an das Gerät.", "Ja, houd uw pas tegen het apparaat.", "Yes, please hold your card to the reader.", "Oui, approchez la carte du terminal.", "Sí, acerque la tarjeta al terminal."], ["j", "Der Betrag ist falsch. Ich habe nur einen Artikel.", "Het bedrag klopt niet. Ik heb maar één artikel.", "The amount is wrong. I only have one item.", "Le montant est faux. Je n'ai qu'un article.", "El importe está mal. Solo llevo un artículo."], ["a", "Oh, entschuldigen Sie. Ich schaue nach.", "O, sorry. Ik kijk even.", "Oh, sorry. Let me check.", "Oh, pardon. Je regarde.", "Ay, perdone. Miro."], ["j", "Haben Sie eine Kundenkarte?", "Heeft u een klantenkaart?", "Do you have a loyalty card?", "Vous avez une carte de fidélité ?", "¿Tienen tarjeta de cliente?"], ["a", "Ja, haben Sie Ihre Karte dabei?", "Ja, heeft u uw kaart bij u?", "Yes, do you have your card with you?", "Oui, vous avez votre carte ?", "Sí, ¿tiene su tarjeta con usted?"], ["j", "Nein, leider nicht. Kann ich eine neue bekommen?", "Nee, helaas niet. Kan ik er een nieuwe krijgen?", "No, unfortunately not. Can I get a new one?", "Non, malheureusement pas. Je peux en avoir une nouvelle ?", "No, por desgracia no. ¿Puedo conseguir una nueva?"], ["a", "Ja, an der Kasse, kostenlos.", "Ja, bij de kassa, gratis.", "Yes, at the checkout, for free.", "Oui, à la caisse, gratuitement.", "Sí, en la caja, gratis."], ["j", "Gibt es heute einen Rabatt?", "Is er vandaag korting?", "Is there a discount today?", "Il y a une réduction aujourd'hui ?", "¿Hay algún descuento hoy?"], ["a", "Ja, zwanzig Prozent auf Obst.", "Ja, twintig procent op fruit.", "Yes, twenty percent off fruit.", "Oui, vingt pour cent sur les fruits.", "Sí, veinte por ciento en fruta."], ["j", "Super! Ich nehme dann die Äpfel.", "Super! Dan neem ik de appels.", "Great! Then I'll take the apples.", "Super ! Je prends alors les pommes.", "¡Genial! Entonces me llevo las manzanas."], ["a", "Haben Sie noch eine Tüte?", "Hebt u nog een tas nodig?", "Do you need another bag?", "Vous voulez encore un sac ?", "¿Necesita otra bolsa?"], ["j", "Ja, bitte. Haben Sie einen Kassenbon?", "Ja, graag. Krijg ik een bonnetje?", "Yes, please. Can I have a receipt?", "Oui, s'il vous plaît. Vous avez un ticket de caisse ?", "Sí, por favor. ¿Me da un ticket?"], ["a", "Hier ist er. Schönen Abend!", "Hier is hij. Fijne avond!", "Here it is. Have a nice evening!", "Le voilà. Bonne soirée !", "Aquí lo tiene. ¡Buenas tardes!"], ["j", "Danke, Ihnen auch!", "Dank je, jij ook!", "Thanks, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"], ["a", "Auf Wiedersehen!", "Tot ziens!", "Goodbye!", "Au revoir !", "¡Adiós!"]]}, {"n": 11, "t": "Kleding: maat, kleur en passen", "tt": {"de": "Kleidung: Größe, Farbe und Anprobieren", "nl": "Kleding: maat, kleur en passen", "en": "Clothes: size, colour and trying on", "fr": "Vêtements : taille, couleur et essayage", "es": "Ropa: talla, color y probarse"}, "r": [["j", "Haben Sie diese Jacke auch in Größe M?", "Hebben jullie deze jas ook in maat M?", "Do you have this jacket in size M?", "Vous avez cette veste en taille M ?", "¿Tienen esta chaqueta en talla M?"], ["a", "Ich schaue nach. Einen Moment.", "Ik kijk even. Eén moment.", "Let me check. One moment.", "Je regarde. Un instant.", "Miro. Un momento."], ["j", "Haben Sie das auch in Schwarz?", "Hebben jullie die ook in zwart?", "Do you have it in black?", "Vous l'avez aussi en noir ?", "¿La tienen también en negro?"], ["a", "Ja, hier ist die Jacke in Schwarz.", "Ja, hier is de jas in zwart.", "Yes, here's the jacket in black.", "Oui, voici la veste en noir.", "Sí, aquí está la chaqueta en negro."], ["j", "Kann ich das anprobieren?", "Mag ik dit passen?", "Can I try this on?", "Je peux l'essayer ?", "¿Puedo probármela?"], ["a", "Natürlich. Die Umkleidekabine ist dort hinten.", "Natuurlijk. De pashokjes zijn daar achterin.", "Of course. The fitting room is at the back.", "Bien sûr. Les cabines sont au fond.", "Claro. El probador está al fondo."], ["j", "Wie passt sie? Ist sie zu klein?", "Hoe zit hij? Is hij te klein?", "How does it fit? Is it too small?", "Comment elle va ? Elle est trop petite ?", "¿Cómo le queda? ¿Es muy pequeña?"], ["a", "Die Größe M passt gut, aber sie ist ein bisschen eng an den Schultern.", "Maat M zit goed, maar hij is een beetje strak bij de schouders.", "Size M fits well, but it's a bit tight at the shoulders.", "La taille M va bien, mais elle est un peu serrée aux épaules.", "La talla M le queda bien, pero está un poco ajustada en los hombros."], ["j", "Haben Sie eine Nummer größer?", "Hebben jullie een maat groter?", "Do you have one size bigger?", "Vous avez une taille au-dessus ?", "¿Tienen una talla más grande?"], ["a", "Ja, Größe L. Einen Moment.", "Ja, maat L. Een moment.", "Yes, size L. One moment.", "Oui, en L. Un instant.", "Sí, en talla L. Un momento."], ["j", "Die passt mir perfekt. Was kostet sie?", "Deze past perfect. Hoeveel kost hij?", "This one fits perfectly. How much is it?", "Celle-ci me va parfaitement. Combien coûte-t-elle ?", "Esta me queda perfecta. ¿Cuánto cuesta?"], ["a", "Sie kostet 79 Euro.", "Die kost 79 euro.", "It costs 79 euros.", "Elle coûte 79 euros.", "Cuesta 79 euros."], ["j", "Gibt es einen Rabatt bei Barzahlung?", "Krijg ik korting als ik contant betaal?", "Is there a discount for paying cash?", "Il y a une réduction si je paie en espèces ?", "¿Hay descuento si pago en efectivo?"], ["a", "Nein, leider nicht. Aber wir haben heute ein Angebot.", "Nee, helaas niet. Maar we hebben vandaag een aanbieding.", "No, unfortunately not. But we have a special offer today.", "Non, malheureusement pas. Mais nous avons une promotion aujourd'hui.", "No, por desgracia no. Pero hoy tenemos una oferta."], ["j", "Kann ich die Jacke umtauschen, wenn sie mir nicht gefällt?", "Kan ik de jas ruilen als hij me toch niet bevalt?", "Can I exchange the jacket if I don't like it?", "Je peux échanger la veste si elle ne me plaît pas ?", "¿Puedo cambiar la chaqueta si no me gusta?"], ["a", "Ja, innerhalb von 14 Tagen mit Kassenbon.", "Ja, binnen veertien dagen met bonnetje.", "Yes, within 14 days with the receipt.", "Oui, dans les 14 jours avec le ticket de caisse.", "Sí, dentro de 14 días con el ticket."], ["j", "Gut, ich nehme sie.", "Oké, ik neem hem.", "Good, I'll take it.", "Très bien, je la prends.", "Bien, me la llevo."], ["a", "Möchten Sie eine Tüte?", "Wilt u een tas?", "Would you like a bag?", "Vous voulez un sac ?", "¿Quiere una bolsa?"], ["j", "Ja, bitte. Danke für Ihre Hilfe.", "Ja, graag. Bedankt voor je hulp.", "Yes, please. Thanks for your help.", "Oui, s'il vous plaît. Merci pour votre aide.", "Sí, por favor. Gracias por su ayuda."], ["a", "Gern geschehen. Einen schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga un buen día!"]]}, {"n": 12, "t": "Hotel: inchecken en reserveren", "tt": {"de": "Hotel: Einchecken und Reservieren", "nl": "Hotel: inchecken en reserveren", "en": "Hotel: checking in and booking", "fr": "Hôtel : arrivée et réservation", "es": "Hotel: registrarse y reservar"}, "r": [["j", "Guten Abend, ich habe ein Zimmer reserviert.", "Goedenavond, ik heb een kamer gereserveerd.", "Good evening, I have a room booked.", "Bonsoir, j'ai réservé une chambre.", "Buenas noches, tengo una habitación reservada."], ["a", "Auf welchen Namen?", "Op welke naam?", "Under what name?", "Au nom de qui ?", "¿A nombre de quién?"], ["j", "Auf den Namen Anna Berg.", "Op de naam Anna Berg.", "Under the name Anna Berg.", "Au nom de Anna Berg.", "A nombre de Anna Berg."], ["a", "Ah, ja. Zwei Nächte, Doppelzimmer. Hier ist Ihr Schlüssel.", "Ah, ja. Twee nachten, tweepersoonskamer. Hier is uw sleutel.", "Ah, yes. Two nights, double room. Here is your key.", "Ah, oui. Deux nuits, chambre double. Voici votre clé.", "Ah, sí. Dos noches, habitación doble. Aquí tiene la llave."], ["j", "Wann gibt es Frühstück?", "Hoe laat is het ontbijt?", "When is breakfast?", "À quelle heure est le petit-déjeuner ?", "¿A qué hora es el desayuno?"], ["a", "Von sieben bis zehn Uhr im Erdgeschoss.", "Van zeven tot tien uur op de begane grond.", "From seven to ten, on the ground floor.", "De sept heures à dix heures, au rez-de-chaussée.", "De siete a diez, en la planta baja."], ["j", "Ist das Frühstück im Preis inbegriffen?", "Is het ontbijt bij de prijs inbegrepen?", "Is breakfast included in the price?", "Le petit-déjeuner est inclus dans le prix ?", "¿El desayuno está incluido en el precio?"], ["a", "Ja, es ist inklusive.", "Ja, het is inbegrepen.", "Yes, it's included.", "Oui, il est inclus.", "Sí, está incluido."], ["j", "Gibt es hier WLAN?", "Is er hier wifi?", "Is there wifi here?", "Il y a le wifi ici ?", "¿Hay wifi aquí?"], ["a", "Ja, das Passwort steht auf Ihrer Karte.", "Ja, het wachtwoord staat op uw kaart.", "Yes, the password is on your card.", "Oui, le mot de passe est sur votre carte.", "Sí, la contraseña está en su tarjeta."], ["j", "Wann muss ich auschecken?", "Hoe laat moet ik uitchecken?", "What time do I need to check out?", "À quelle heure dois-je libérer la chambre ?", "¿A qué hora tengo que dejar la habitación?"], ["a", "Bis elf Uhr am Morgen.", "Tot elf uur 's ochtends.", "By eleven in the morning.", "Avant onze heures du matin.", "Antes de las once de la mañana."], ["j", "Kann ich mein Gepäck hier lassen, wenn ich später komme?", "Kan ik mijn bagage hier laten als ik later kom?", "Can I leave my luggage here if I come back later?", "Je peux laisser mes bagages ici si je reviens plus tard ?", "¿Puedo dejar mi equipaje aquí si vuelvo más tarde?"], ["a", "Ja, natürlich. Wir bewahren es für Sie auf.", "Ja, natuurlijk. Wij bewaren het voor u.", "Yes, of course. We'll keep it for you.", "Oui, bien sûr. Nous le garderons pour vous.", "Sí, claro. Lo guardamos para usted."], ["j", "Haben Sie für morgen noch ein Zimmer frei?", "Hebben jullie morgen nog een kamer vrij?", "Do you have a room free for tomorrow?", "Vous avez une chambre libre pour demain ?", "¿Tienen una habitación libre para mañana?"], ["a", "Ja, aber nur noch eine Einzelzimmer.", "Ja, maar alleen nog een eenpersoonskamer.", "Yes, but only a single room left.", "Oui, mais il ne reste qu'une chambre simple.", "Sí, pero solo queda una individual."], ["j", "Das ist in Ordnung. Danke!", "Dat is goed. Dank je!", "That's fine. Thanks!", "Ça me va. Merci !", "Está bien. ¡Gracias!"], ["a", "Gern geschehen. Gute Nacht!", "Graag gedaan. Welterusten!", "You're welcome. Good night!", "Avec plaisir. Bonne nuit !", "De nada. ¡Buenas noches!"]]}, {"n": 13, "t": "Hotel: klacht over de kamer", "tt": {"de": "Hotel: Beschwerde über das Zimmer", "nl": "Hotel: klacht over de kamer", "en": "Hotel: a complaint about the room", "fr": "Hôtel : une réclamation sur la chambre", "es": "Hotel: una queja sobre la habitación"}, "r": [["j", "Entschuldigung, in meinem Zimmer ist es sehr kalt.", "Sorry, in mijn kamer is het erg koud.", "Excuse me, my room is very cold.", "Excusez-moi, il fait très froid dans ma chambre.", "Perdone, en mi habitación hace mucho frío."], ["a", "Oh, das tut mir leid. Ich schaue nach der Heizung.", "Oh, wat vervelend. Ik kijk even naar de verwarming.", "Oh, I'm sorry. I'll check the heating.", "Oh, je suis désolé. Je vais vérifier le chauffage.", "Lo siento. Miro la calefacción."], ["j", "Kann ich ein anderes Zimmer bekommen?", "Kan ik een andere kamer krijgen?", "Can I get a different room?", "Je peux avoir une autre chambre ?", "¿Puedo cambiar de habitación?"], ["a", "Ja, ich kann Ihnen ein Zimmer im dritten Stock geben.", "Ja, ik kan u een kamer op de derde verdieping geven.", "Yes, I can give you a room on the third floor.", "Oui, je peux vous donner une chambre au troisième étage.", "Sí, le puedo dar una habitación en la tercera planta."], ["j", "Ist das Zimmer ruhiger?", "Is die kamer rustiger?", "Is that room quieter?", "Cette chambre est plus calme ?", "¿Esa habitación es más tranquila?"], ["a", "Ja, es liegt zur Rückseite des Hotels.", "Ja, hij ligt aan de achterkant van het hotel.", "Yes, it faces the back of the hotel.", "Oui, elle donne sur l'arrière de l'hôtel.", "Sí, da a la parte trasera del hotel."], ["j", "Ich habe auch kein warmes Wasser im Bad.", "Ik heb ook geen warm water in de badkamer.", "I also have no hot water in the bathroom.", "Je n'ai pas non plus d'eau chaude dans la salle de bain.", "Tampoco tengo agua caliente en el baño."], ["a", "Das ist nicht gut. Ich rufe den Techniker.", "Dat is niet goed. Ik bel de monteur.", "That's not good. I'll call the technician.", "Ce n'est pas bien. J'appelle le technicien.", "Eso no está bien. Llamo al técnico."], ["j", "Wie lange dauert das ungefähr?", "Hoe lang duurt dat ongeveer?", "How long will that take roughly?", "Ça prendra combien de temps environ ?", "¿Cuánto tardará más o menos?"], ["a", "Etwa eine halbe Stunde.", "Ongeveer een half uur.", "About half an hour.", "Environ une demi-heure.", "Unos treinta minutos."], ["j", "Gut, ich warte. Danke.", "Oké, ik wacht. Dank je.", "Okay, I'll wait. Thanks.", "D'accord, j'attends. Merci.", "Vale, espero. Gracias."], ["a", "Ich bringe Ihnen einen Tee, während Sie warten.", "Ik breng u thee terwijl u wacht.", "I'll bring you a tea while you wait.", "Je vous apporte un thé en attendant.", "Le traigo un té mientras espera."], ["j", "Das ist sehr nett. Danke!", "Dat is erg aardig. Bedankt!", "That's very kind. Thanks!", "C'est très gentil. Merci !", "Qué amable. ¡Gracias!"], ["a", "Gern geschehen. Ich sage Bescheid, wenn das Zimmer fertig ist.", "Graag gedaan. Ik laat u weten als de kamer klaar is.", "You're welcome. I'll let you know when the room is ready.", "Avec plaisir. Je vous préviens quand la chambre sera prête.", "De nada. Le aviso cuando la habitación esté lista."]]}, {"n": 14, "t": "Apotheek: vragen over een medicijn", "tt": {"de": "Apotheke: Fragen zu einem Medikament", "nl": "Apotheek: vragen over een medicijn", "en": "Pharmacy: questions about a medicine", "fr": "Pharmacie : questions sur un médicament", "es": "Farmacia: preguntas sobre un medicamento"}, "r": [["j", "Guten Tag, ich brauche etwas gegen Kopfschmerzen.", "Hallo, ik heb iets nodig tegen hoofdpijn.", "Hi, I need something for a headache.", "Bonjour, il me faudrait quelque chose contre les maux de tête.", "Hola, necesito algo para el dolor de cabeza."], ["a", "Haben Sie ein Rezept?", "Heeft u een recept?", "Do you have a prescription?", "Vous avez une ordonnance ?", "¿Tiene receta?"], ["j", "Nein, ich habe kein Rezept. Was können Sie empfehlen?", "Nee, ik heb geen recept. Wat kunt u aanraden?", "No, I don't have a prescription. What can you recommend?", "Non, je n'ai pas d'ordonnance. Que me conseillez-vous ?", "No, no tengo receta. ¿Qué me recomienda?"], ["a", "Paracetamol ist gut. Nehmen Sie es mit Wasser.", "Paracetamol is goed. Neem het met water in.", "Paracetamol is good. Take it with water.", "Le paracétamol convient bien. Prenez-le avec de l'eau.", "El paracetamol va bien. Tómelo con agua."], ["j", "Wie oft darf ich das nehmen?", "Hoe vaak mag ik dat innemen?", "How often can I take it?", "Je peux en prendre combien de fois ?", "¿Cada cuánto lo puedo tomar?"], ["a", "Alle vier bis sechs Stunden, nicht öfter als vier Mal am Tag.", "Elke vier tot zes uur, niet vaker dan vier keer per dag.", "Every four to six hours, no more than four times a day.", "Toutes les quatre à six heures, pas plus de quatre fois par jour.", "Cada cuatro a seis horas, no más de cuatro veces al día."], ["j", "Darf ich das mit Alkohol nehmen?", "Mag ik dit innemen met alcohol?", "Can I take this with alcohol?", "Je peux le prendre avec de l'alcool ?", "¿Puedo tomarlo con alcohol?"], ["a", "Nein, das ist nicht empfohlen. Fragen Sie bei Zweifeln den Apotheker.", "Nee, dat wordt afgeraden. Vraag het de apotheker bij twijfel.", "No, that's not advised. Ask the pharmacist if you're unsure.", "Non, ce n'est pas recommandé. Demandez au pharmacien en cas de doute.", "No, no es recomendable. Pregunte al farmacéutico si tiene dudas."], ["j", "Ich nehme auch andere Tabletten. Gibt es Wechselwirkungen?", "Ik gebruik ook andere pillen. Zijn er wisselwerkingen?", "I also take other tablets. Are there interactions?", "Je prends aussi d'autres comprimés. Il y a des interactions ?", "También tomo otras pastillas. ¿Hay interacciones?"], ["a", "Sagen Sie mir bitte, welche Tabletten das sind.", "Zeg me alstublieft welke pillen het zijn.", "Please tell me which tablets they are.", "Dites-moi lesquels, s'il vous plaît.", "Dígame cuáles son, por favor."], ["j", "Eine Tablette gegen Bluthochdruck und eine gegen Allergie.", "Een pil tegen hoge bloeddruk en een tegen allergie.", "One for high blood pressure and one for allergies.", "Un pour la tension et un pour les allergies.", "Una para la presión alta y otra para la alergia."], ["a", "Dann sollten Sie vorher mit Ihrem Arzt sprechen.", "Dan kunt u het beste eerst met uw arts overleggen.", "Then you should talk to your doctor first.", "Dans ce cas, parlez-en d'abord à votre médecin.", "En ese caso, hable antes con su médico."], ["j", "Okay. Ich nehme eine Packung Paracetamol, bitte.", "Oké. Ik neem een doosje paracetamol, alstublieft.", "Okay. I'll take a pack of paracetamol, please.", "D'accord. Je prends une boîte de paracétamol, s'il vous plaît.", "Vale. Me llevo una caja de paracetamol, por favor."], ["a", "Das macht sechs Euro achtzig.", "Dat is zes euro tachtig.", "That's six euros eighty.", "Ça fait six euros quatre-vingts.", "Son seis euros con ochenta."], ["j", "Danke. Gute Besserung!", "Dank je. Beterschap!", "Thanks. Get well soon!", "Merci. Bon courage !", "Gracias. ¡Que se mejore!"], ["a", "Danke, auf Wiedersehen.", "Dank u, tot ziens.", "Thank you, goodbye.", "Merci, au revoir.", "Gracias, adiós."]]}, {"n": 15, "t": "Dokter: klachten uitleggen", "tt": {"de": "Arzt: Beschwerden erklären", "nl": "Dokter: klachten uitleggen", "en": "Doctor: explaining your symptoms", "fr": "Médecin : expliquer ses symptômes", "es": "Médico: explicar los síntomas"}, "r": [["j", "Guten Tag, ich bin hier wegen meiner Halsschmerzen.", "Goedemiddag, ik ben hier vanwege keelpijn.", "Hello, I'm here because of a sore throat.", "Bonjour, je viens pour un mal de gorge.", "Buenos días, vengo por un dolor de garganta."], ["a", "Seit wann haben Sie die Schmerzen?", "Sinds wanneer heeft u die pijn?", "Since when have you had the pain?", "Depuis quand avez-vous mal ?", "¿Desde cuándo tiene el dolor?"], ["j", "Seit gestern Abend. Und ich habe auch Fieber.", "Sinds gisteravond. En ik heb ook koorts.", "Since last night. And I also have a fever.", "Depuis hier soir. Et j'ai aussi de la fièvre.", "Desde anoche. Y también tengo fiebre."], ["a", "Wie hoch ist das Fieber? Haben Sie es gemessen?", "Hoe hoog is de koorts? Heeft u het gemeten?", "How high is the fever? Have you measured it?", "Quelle est la température ? Vous l'avez mesurée ?", "¿Qué temperatura tiene? ¿Se la ha medido?"], ["j", "Ja, achtunddreißig Komma acht Grad.", "Ja, achtendertig komma acht graden.", "Yes, thirty-eight point eight degrees.", "Oui, trente-huit virgule huit degrés.", "Sí, treinta y ocho coma ocho grados."], ["a", "Haben Sie auch Husten oder Schnupfen?", "Heeft u ook hoest of een verkoudheid?", "Do you also have a cough or a cold?", "Vous avez aussi de la toux ou un rhume ?", "¿También tiene tos o resfriado?"], ["j", "Ich habe ein bisschen Husten, aber keinen Schnupfen.", "Ik heb een beetje hoest, maar geen verkoudheid.", "I have a little cough, but no runny nose.", "J'ai un peu de toux, mais pas de rhume.", "Tengo un poco de tos, pero no estoy resfriado."], ["a", "Machen Sie bitte den Mund auf. Ihr Hals ist sehr rot.", "Doe uw mond eens open. Uw keel is erg rood.", "Please open your mouth. Your throat is very red.", "Ouvrez la bouche, s'il vous plaît. Votre gorge est très rouge.", "Abra la boca, por favor. Tiene la garganta muy roja."], ["j", "Ist das schlimm? Brauche ich Antibiotika?", "Is dat erg? Heb ik antibiotica nodig?", "Is it serious? Do I need antibiotics?", "C'est grave ? J'ai besoin d'antibiotiques ?", "¿Es grave? ¿Necesito antibióticos?"], ["a", "Ich denke, es ist eine Virusinfektion. Antibiotika helfen da nicht.", "Ik denk dat het een virusinfectie is. Antibiotica helpen dan niet.", "I think it's a viral infection. Antibiotics won't help with that.", "Je pense que c'est une infection virale. Les antibiotiques ne serviront à rien.", "Creo que es una infección viral. Los antibióticos no ayudan en ese caso."], ["j", "Was kann ich dann tun?", "Wat kan ik dan doen?", "What can I do then?", "Qu'est-ce que je peux faire alors ?", "¿Qué puedo hacer entonces?"], ["a", "Viel trinken, sich ausruhen und ein fiebersenkendes Mittel nehmen.", "Veel drinken, rusten en een koortswerend middel nemen.", "Drink plenty, rest, and take something for the fever.", "Buvez beaucoup, reposez-vous et prenez un médicament contre la fièvre.", "Beba mucho líquido, descanse y tome algo para la fiebre."], ["j", "Wann muss ich wieder kommen?", "Wanneer moet ik terugkomen?", "When do I need to come back?", "Quand dois-je revenir ?", "¿Cuándo tengo que volver?"], ["a", "Wenn es nach drei Tagen nicht besser ist, oder wenn Sie schlechter atmen.", "Als het na drie dagen niet beter is, of als u moeilijker ademt.", "If it's not better after three days, or if your breathing gets worse.", "Si ça ne va pas mieux après trois jours, ou si vous avez plus de mal à respirer.", "Si después de tres días no mejora, o si le cuesta más respirar."], ["j", "Danke, Herr Doktor. Auf Wiedersehen.", "Dank u, dokter. Tot ziens.", "Thank you, doctor. Goodbye.", "Merci, docteur. Au revoir.", "Gracias, doctor. Adiós."], ["a", "Gute Besserung! Auf Wiedersehen.", "Beterschap! Tot ziens.", "Get well soon! Goodbye.", "Bon rétablissement ! Au revoir.", "¡Que se mejore! Adiós."]]}, {"n": 16, "t": "Afspraak maken en afzeggen", "tt": {"de": "Termin vereinbaren und absagen", "nl": "Afspraak maken en afzeggen", "en": "Making and cancelling an appointment", "fr": "Prendre et annuler un rendez-vous", "es": "Pedir y anular una cita"}, "r": [["j", "Guten Tag, ich möchte einen Termin machen.", "Hallo, ik wil graag een afspraak maken.", "Hello, I'd like to make an appointment.", "Bonjour, je voudrais prendre rendez-vous.", "Hola, quisiera pedir una cita."], ["a", "Gerne. Für wann möchten Sie kommen?", "Graag. Wanneer wilt u komen?", "Sure. When would you like to come?", "Bien sûr. Pour quand souhaitez-vous venir ?", "Claro. ¿Para cuándo quiere venir?"], ["j", "Hätten Sie nächste Woche Dienstag Zeit?", "Hebben jullie volgende week dinsdag een plek?", "Do you have time next Tuesday?", "Vous avez de la disponibilité mardi prochain ?", "¿Tienen hueco el martes que viene?"], ["a", "Am Dienstag um zehn Uhr oder um vierzehn Uhr.", "Dinsdag om tien uur of om twee uur.", "On Tuesday at ten or at two.", "Mardi à dix heures ou à quatorze heures.", "El martes a las diez o a las dos."], ["j", "Um zehn Uhr, bitte.", "Om tien uur, graag.", "At ten, please.", "À dix heures, s'il vous plaît.", "A las diez, por favor."], ["a", "Wie ist Ihr Name und Ihr Geburtsdatum?", "Wat is uw naam en geboortedatum?", "What is your name and date of birth?", "Quel est votre nom et votre date de naissance ?", "¿Cuál es su nombre y fecha de nacimiento?"], ["j", "Anna Berg, geboren am 3. Mai 1990.", "Anna Berg, geboren op 3 mei 1990.", "Anna Berg, born on 3 May 1990.", "Anna Berg, née le 3 mai 1990.", "Anna Berg, nacida el 3 de mayo de 1990."], ["a", "Gut, Ihr Termin ist am Dienstag um zehn Uhr.", "Goed, uw afspraak is dinsdag om tien uur.", "Good, your appointment is Tuesday at ten.", "Très bien, votre rendez-vous est mardi à dix heures.", "Bien, su cita es el martes a las diez."], ["j", "Muss ich etwas mitbringen?", "Moet ik iets meenemen?", "Do I need to bring anything?", "Je dois apporter quelque chose ?", "¿Tengo que traer algo?"], ["a", "Ja, bitte Ihre Versichertenkarte und den Ausweis.", "Ja, graag uw verzekeringspas en identiteitsbewijs.", "Yes, please bring your insurance card and ID.", "Oui, apportez votre carte d'assurance et votre pièce d'identité.", "Sí, traiga su tarjeta de seguro y su documento de identidad."], ["j", "Ich muss den Termin leider absagen.", "Helaas moet ik de afspraak afzeggen.", "Unfortunately I need to cancel the appointment.", "Malheureusement, je dois annuler le rendez-vous.", "Lamentablemente tengo que cancelar la cita."], ["a", "Kein Problem. Wann können Sie wieder kommen?", "Geen probleem. Wanneer kunt u weer komen?", "No problem. When can you come back?", "Pas de problème. Quand pouvez-vous revenir ?", "No hay problema. ¿Cuándo puede volver?"], ["j", "Vielleicht in zwei Wochen. Kann ich das später sagen?", "Misschien over twee weken. Kan ik dat later laten weten?", "Maybe in two weeks. Can I tell you later?", "Peut-être dans deux semaines. Je peux vous le dire plus tard ?", "Quizás en dos semanas. ¿Puedo decírselo más tarde?"], ["a", "Ja, rufen Sie einfach wieder an.", "Ja, bel gewoon weer.", "Yes, just call again.", "Oui, rappelez simplement.", "Sí, simplemente vuelva a llamar."], ["j", "Wie kann ich den Termin verschieben?", "Hoe kan ik de afspraak verzetten?", "How can I reschedule the appointment?", "Comment puis-je reporter le rendez-vous ?", "¿Cómo puedo cambiar la cita de fecha?"], ["a", "Am Telefon oder über unsere Website.", "Telefonisch of via onze website.", "By phone or through our website.", "Par téléphone ou sur notre site.", "Por teléfono o en nuestra web."], ["j", "Gut. Vielen Dank für Ihre Hilfe.", "Goed. Heel erg bedankt voor je hulp.", "Good. Thank you very much for your help.", "Bien. Merci beaucoup pour votre aide.", "Bien. Muchas gracias por su ayuda."], ["a", "Gern geschehen. Auf Wiederhören!", "Graag gedaan. Tot ziens!", "You're welcome. Goodbye!", "Avec plaisir. Au revoir !", "De nada. ¡Hasta luego!"]]}, {"n": 17, "t": "Openingstijden en informatie vragen", "tt": {"de": "Öffnungszeiten und Informationen erfragen", "nl": "Openingstijden en informatie vragen", "en": "Asking about opening hours and information", "fr": "Demander les horaires et des informations", "es": "Preguntar el horario y pedir información"}, "r": [["j", "Entschuldigung, wann öffnen Sie morgen?", "Excuseer, hoe laat openen jullie morgen?", "Excuse me, when do you open tomorrow?", "Excusez-moi, à quelle heure ouvrez-vous demain ?", "Perdone, ¿a qué hora abren mañana?"], ["a", "Um neun Uhr.", "Om negen uur.", "At nine o'clock.", "À neuf heures.", "A las nueve."], ["j", "Und am Sonntag?", "En op zondag?", "And on Sunday?", "Et dimanche ?", "¿Y el domingo?"], ["a", "Am Sonntag sind wir geschlossen.", "Op zondag zijn we gesloten.", "On Sunday we're closed.", "Le dimanche, nous sommes fermés.", "El domingo estamos cerrados."], ["j", "Bis wann ist heute geöffnet?", "Tot hoe laat is het vandaag open?", "Until what time are you open today?", "Vous êtes ouverts jusqu'à quelle heure aujourd'hui ?", "¿Hasta qué hora están abiertos hoy?"], ["a", "Bis achtzehn Uhr.", "Tot zes uur.", "Until six p.m.", "Jusqu'à dix-huit heures.", "Hasta las seis de la tarde."], ["j", "Gibt es hier eine Mittagspause?", "Is er hier een lunchpauze?", "Is there a lunch break?", "Il y a une pause déjeuner ?", "¿Hay pausa para comer?"], ["a", "Ja, von zwölf bis dreizehn Uhr.", "Ja, van twaalf tot één uur.", "Yes, from twelve to one.", "Oui, de midi à treize heures.", "Sí, de doce a una."], ["j", "Wie kann ich Sie erreichen, wenn es geschlossen ist?", "Hoe kan ik u bereiken als u gesloten bent?", "How can I reach you when you're closed?", "Comment peut-on vous joindre quand vous êtes fermés ?", "¿Cómo puedo contactarle si está cerrado?"], ["a", "Über die E-Mail oder die Nummer auf der Website.", "Via de e-mail of het nummer op de website.", "By email or the number on the website.", "Par e-mail ou au numéro indiqué sur le site.", "Por correo o con el número de la web."], ["j", "Haben Sie auch einen Parkplatz?", "Hebben jullie ook een parkeerplaats?", "Do you also have a parking space?", "Vous avez aussi un parking ?", "¿Tienen también aparcamiento?"], ["a", "Ja, direkt vor dem Gebäude, aber nur zwei Stunden.", "Ja, direct voor het gebouw, maar alleen twee uur.", "Yes, right in front of the building, but only for two hours.", "Oui, juste devant le bâtiment, mais seulement deux heures.", "Sí, justo delante del edificio, pero solo dos horas."], ["j", "Ist der Eingang auch rollstuhlgerecht?", "Is de ingang ook geschikt voor een rolstoel?", "Is the entrance also wheelchair accessible?", "L'entrée est-elle accessible en fauteuil roulant ?", "¿La entrada también es accesible para silla de ruedas?"], ["a", "Ja, es gibt eine Rampe an der Seite.", "Ja, aan de zijkant is een oprit.", "Yes, there's a ramp on the side.", "Oui, il y a une rampe sur le côté.", "Sí, hay una rampa en el lateral."], ["j", "Danke für die Information.", "Dank je voor de informatie.", "Thanks for the information.", "Merci pour les informations.", "Gracias por la información."], ["a", "Gern geschehen. Schönen Tag!", "Graag gedaan. Fijne dag!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]]}, {"n": 18, "t": "Bank en post", "tt": {"de": "Bank und Post", "nl": "Bank en post", "en": "Bank and post office", "fr": "Banque et poste", "es": "Banco y correos"}, "r": [["j", "Guten Tag, ich möchte ein Paket verschicken.", "Hallo, ik wil graag een pakket versturen.", "Hello, I'd like to send a parcel.", "Bonjour, je voudrais envoyer un colis.", "Hola, quisiera enviar un paquete."], ["a", "Wohin soll es gehen?", "Waar moet het naartoe?", "Where is it going?", "Vers où ?", "¿A dónde va?"], ["j", "Nach Deutschland, Berlin.", "Naar Duitsland, Berlijn.", "To Germany, Berlin.", "En Allemagne, à Berlin.", "A Alemania, a Berlín."], ["a", "Das kostet 12 Euro, mit Versicherung 15 Euro.", "Dat kost twaalf euro, met verzekering vijftien euro.", "That's twelve euros, or fifteen with insurance.", "Ça coûte douze euros, quinze avec l'assurance.", "Cuesta doce euros, o quince con seguro."], ["j", "Mit Versicherung, bitte. Wie lange dauert es?", "Met verzekering, alstublieft. Hoe lang duurt het?", "With insurance, please. How long does it take?", "Avec assurance, s'il vous plaît. Ça prend combien de temps ?", "Con seguro, por favor. ¿Cuánto tarda?"], ["a", "Etwa drei bis fünf Werktage.", "Ongeveer drie tot vijf werkdagen.", "About three to five working days.", "Environ trois à cinq jours ouvrables.", "Unos tres a cinco días laborables."], ["j", "Ich möchte auch Geld auf mein Konto einzahlen.", "Ik wil ook geld storten op mijn rekening.", "I'd also like to deposit money into my account.", "Je voudrais aussi déposer de l'argent sur mon compte.", "También quisiera ingresar dinero en mi cuenta."], ["a", "Haben Sie Ihre Bankkarte und Ihren Ausweis dabei?", "Heeft u uw bankpas en identiteitsbewijs bij u?", "Do you have your bank card and ID with you?", "Vous avez votre carte bancaire et votre pièce d'identité ?", "¿Tiene su tarjeta bancaria y su documento de identidad?"], ["j", "Ja, hier sind sie.", "Ja, hier zijn ze.", "Yes, here they are.", "Oui, les voici.", "Sí, aquí están."], ["a", "Wie viel möchten Sie einzahlen?", "Hoeveel wilt u storten?", "How much would you like to deposit?", "Combien voulez-vous déposer ?", "¿Cuánto quiere ingresar?"], ["j", "Hundert Euro, bitte.", "Honderd euro, alstublieft.", "One hundred euros, please.", "Cent euros, s'il vous plaît.", "Cien euros, por favor."], ["a", "Gut. Bitte unterschreiben Sie hier.", "Goed. Wilt u hier tekenen.", "Good. Please sign here.", "Bien. Signez ici, s'il vous plaît.", "Bien. Firme aquí, por favor."], ["j", "Kann ich auch einen Kontoauszug bekommen?", "Kan ik ook een rekeningoverzicht krijgen?", "Can I also get an account statement?", "Je peux aussi avoir un relevé de compte ?", "¿Puedo también obtener un extracto de cuenta?"], ["a", "Ja, er kommt gleich aus dem Drucker.", "Ja, die komt zo uit de printer.", "Yes, it'll come out of the printer shortly.", "Oui, il sort de l'imprimante dans un instant.", "Sí, saldrá enseguida de la impresora."], ["j", "Danke, das war sehr hilfreich.", "Dank je, dat was erg fijn.", "Thanks, that was very helpful.", "Merci, c'était très utile.", "Gracias, me ha sido muy útil."], ["a", "Gern geschehen. Einen schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]]}, {"n": 19, "t": "Noodgeval: hulp roepen en eerste hulp", "tt": {"de": "Notfall: Hilfe rufen und Erste Hilfe", "nl": "Noodgeval: hulp roepen en eerste hulp", "en": "Emergency: calling for help and first aid", "fr": "Urgence : appeler à l'aide et premiers secours", "es": "Emergencia: pedir ayuda y primeros auxilios"}, "r": [["j", "Hilfe! Bitte helfen Sie mir!", "Help! Help me alstublieft!", "Help! Please help me!", "Au secours ! Aidez-moi, s'il vous plaît !", "¡Socorro! ¡Por favor, ayúdeme!"], ["a", "Was ist passiert?", "Wat is er gebeurd?", "What happened?", "Qu'est-ce qui s'est passé ?", "¿Qué ha pasado?"], ["j", "Mein Freund ist gestürzt. Er blutet am Kopf.", "Mijn vriend is gevallen. Hij bloedt aan zijn hoofd.", "My friend fell. He's bleeding from his head.", "Mon ami est tombé. Il saigne à la tête.", "Mi amigo se ha caído. Sangra de la cabeza."], ["a", "Rufen Sie sofort den Notruf, die 112.", "Bel meteen het alarmnummer, de 112.", "Call emergency services right away, 112.", "Appelez tout de suite les urgences, le 112.", "Llame ya a emergencias, al 112."], ["j", "Ich rufe jetzt an. Wo sind wir hier?", "Ik bel nu. Waar zijn we hier?", "I'm calling now. Where are we?", "J'appelle maintenant. On est où ici ?", "Llamo ahora. ¿Dónde estamos?"], ["a", "Sagen Sie die Straße und die Hausnummer.", "Zeg de straat en het huisnummer.", "Tell them the street and the house number.", "Donnez la rue et le numéro.", "Diga la calle y el número de la casa."], ["j", "Wir sind in der Hauptstraße, Nummer dreizehn.", "We zijn op de hoofdstraat, nummer dertien.", "We're on the main street, number thirteen.", "Nous sommes dans la rue principale, numéro treize.", "Estamos en la calle principal, número trece."], ["a", "Legen Sie ihn hin und halten Sie den Kopf still.", "Leg hem neer en houd zijn hoofd stil.", "Lay him down and keep his head still.", "Allongez-le et gardez la tête immobile.", "Acuéstelo y mantenga la cabeza quieta."], ["j", "Er ist wach, aber er ist sehr blass.", "Hij is wakker, maar hij is erg bleek.", "He's awake, but he's very pale.", "Il est conscient, mais il est très pâle.", "Está consciente, pero está muy pálido."], ["a", "Decken Sie ihn zu, damit er nicht auskühlt.", "Dek hem toe, zodat hij niet afkoelt.", "Cover him so he doesn't get cold.", "Couvrez-le pour éviter qu'il ne refroidisse.", "Cúbralo para que no se enfríe."], ["j", "Soll ich ihm Wasser geben?", "Moet ik hem water geven?", "Should I give him water?", "Je peux lui donner de l'eau ?", "¿Le doy agua?"], ["a", "Nein, nichts zu trinken, bis der Rettungsdienst da ist.", "Nee, niets te drinken tot de ambulance er is.", "No, nothing to drink until the ambulance arrives.", "Non, rien à boire avant l'arrivée des secours.", "No, nada de beber hasta que llegue la ambulancia."], ["j", "Die Sanitäter kommen gleich. Danke!", "De ambulance komt er zo aan. Dank je!", "The paramedics are coming now. Thanks!", "Les secours arrivent. Merci !", "Ya vienen los paramédicos. ¡Gracias!"], ["a", "Gut. Bleiben Sie bei ihm und sprechen Sie mit ihm.", "Goed. Blijf bij hem en praat met hem.", "Good. Stay with him and keep talking to him.", "Bien. Restez avec lui et parlez-lui.", "Bien. Quédese con él y hable con él."], ["j", "Ich bleibe hier. Alles wird gut.", "Ik blijf hier. Het komt goed.", "I'm staying here. It'll be alright.", "Je reste ici. Tout va bien aller.", "Me quedo aquí. Todo va a salir bien."], ["a", "Danke. Wir sind sehr froh, dass Sie geholfen haben.", "Dank u. We zijn blij dat u hebt geholpen.", "Thank you. We're very glad you helped.", "Merci. Nous sommes très reconnaissants de votre aide.", "Gracias. Nos alegra mucho que haya ayudado."]]}, {"n": 20, "t": "Politie en verloren spullen", "tt": {"de": "Polizei und verlorene Sachen", "nl": "Politie en verloren spullen", "en": "Police and lost property", "fr": "Police et objets perdus", "es": "Policía y objetos perdidos"}, "r": [["j", "Entschuldigung, ich habe meine Tasche verloren.", "Excuseer, ik ben mijn tas kwijt.", "Excuse me, I've lost my bag.", "Excusez-moi, j'ai perdu mon sac.", "Perdone, he perdido mi bolso."], ["a", "Wann und wo haben Sie sie verloren?", "Wanneer en waar bent u hem kwijtgeraakt?", "When and where did you lose it?", "Quand et où l'avez-vous perdu ?", "¿Cuándo y dónde lo perdió?"], ["j", "Heute Morgen, im Bus Nummer vier.", "Vanochtend, in bus vier.", "This morning, on bus number four.", "Ce matin, dans le bus numéro quatre.", "Esta mañana, en el autobús número cuatro."], ["a", "Wie sieht die Tasche aus?", "Hoe ziet de tas eruit?", "What does the bag look like?", "À quoi ressemble le sac ?", "¿Cómo es el bolso?"], ["j", "Sie ist braun, aus Leder, mit einem roten Schlüsselanhänger.", "Hij is bruin, van leer, met een rode sleutelhanger.", "It's brown, made of leather, with a red keyring.", "Il est marron, en cuir, avec un porte-clés rouge.", "Es marrón, de piel, con un llavero rojo."], ["a", "Ich schaue im Fundbüro nach. Füllen Sie bitte dieses Formular aus.", "Ik kijk in de gevonden voorwerpen. Vul dit formulier in.", "I'll check the lost property office. Please fill in this form.", "Je vais vérifier au bureau des objets trouvés. Remplissez ce formulaire.", "Miro en objetos perdidos. Rellene este formulario."], ["j", "Was muss ich hier eintragen?", "Wat moet ik hier invullen?", "What do I need to write here?", "Qu'est-ce que je dois écrire ici ?", "¿Qué tengo que poner aquí?"], ["a", "Ihren Namen, Ihre Adresse und eine Telefonnummer.", "Uw naam, adres en telefoonnummer.", "Your name, address and a phone number.", "Votre nom, votre adresse et un numéro de téléphone.", "Su nombre, su dirección y un número de teléfono."], ["j", "Ist in der Tasche etwas Wichtiges? Ein Ausweis?", "Zit er iets belangrijks in de tas? Een identiteitsbewijs?", "Is there anything important in the bag? An ID?", "Il y a quelque chose d'important dedans ? Une pièce d'identité ?", "¿Hay algo importante dentro? ¿Un documento de identidad?"], ["a", "Ja, und Sie müssen auch eine Anzeige bei der Polizei machen.", "Ja, en u moet ook aangifte doen bij de politie.", "Yes, and you also have to report it to the police.", "Oui, et vous devez aussi faire une déclaration à la police.", "Sí, y también tiene que presentar una denuncia en la policía."], ["j", "Wo ist die nächste Polizeistation?", "Waar is het dichtstbijzijnde politiebureau?", "Where is the nearest police station?", "Où est le commissariat le plus proche ?", "¿Dónde está la comisaría más cercana?"], ["a", "Gleich um die Ecke, in der Hauptstraße.", "Vlakbij, op de hoofdstraat.", "Just around the corner, on the main street.", "Juste au coin, dans la rue principale.", "A la vuelta de la esquina, en la calle principal."], ["j", "Kann ich die Anzeige online machen?", "Kan ik de aangifte ook online doen?", "Can I report it online?", "Je peux faire la déclaration en ligne ?", "¿Puedo presentar la denuncia en línea?"], ["a", "Ja, auf der Website der Polizei, mit Ihrer Nummer.", "Ja, op de website van de politie, met uw nummer.", "Yes, on the police website, with your reference number.", "Oui, sur le site de la police, avec votre numéro.", "Sí, en la web de la policía, con su número."], ["j", "Danke, Sie haben mir sehr geholfen.", "Dank je, je hebt me erg geholpen.", "Thanks, you've been very helpful.", "Merci, vous m'avez beaucoup aidé.", "Gracias, me ha ayudado mucho."], ["a", "Viel Glück! Ich hoffe, Sie finden die Tasche.", "Veel succes! Ik hoop dat u de tas vindt.", "Good luck! I hope you find the bag.", "Bonne chance ! J'espère que vous retrouverez le sac.", "¡Mucha suerte! Espero que encuentre el bolso."]]}, {"n": 21, "t": "Telefoon en internet: storing melden", "tt": {"de": "Telefon und Internet: Störung melden", "nl": "Telefoon en internet: storing melden", "en": "Phone and internet: reporting a fault", "fr": "Téléphone et internet : signaler une panne", "es": "Teléfono e internet: avisar de una avería"}, "r": [["j", "Guten Tag, mein Internet funktioniert nicht.", "Hallo, mijn internet werkt niet.", "Hello, my internet isn't working.", "Bonjour, mon internet ne fonctionne pas.", "Hola, mi internet no funciona."], ["a", "Seit wann haben Sie das Problem?", "Sinds wanneer heeft u dit probleem?", "Since when have you had this problem?", "Depuis quand avez-vous ce problème ?", "¿Desde cuándo tiene este problema?"], ["j", "Seit heute Morgen. Die Lampe am Router blinkt rot.", "Sinds vanmorgen. Het lampje van de router knippert rood.", "Since this morning. The light on the router is blinking red.", "Depuis ce matin. Le voyant du routeur clignote en rouge.", "Desde esta mañana. La luz del router parpadea en rojo."], ["a", "Haben Sie den Router schon einmal neu gestartet?", "Heeft u de router al eens opnieuw opgestart?", "Have you restarted the router yet?", "Vous avez déjà redémarré le routeur ?", "¿Ya ha reiniciado el router?"], ["j", "Ja, zweimal. Es hat nichts geholfen.", "Ja, twee keer. Het heeft niets geholpen.", "Yes, twice. It didn't help.", "Oui, deux fois. Ça n'a rien changé.", "Sí, dos veces. No ha servido de nada."], ["a", "Dann melden wir die Störung. Wie ist Ihre Kundennummer?", "Dan melden we de storing. Wat is uw klantnummer?", "Then we'll report the outage. What's your customer number?", "Alors nous signalons la panne. Quel est votre numéro client ?", "Entonces registramos la avería. ¿Cuál es su número de cliente?"], ["j", "Die Nummer ist auf dem Vertrag. Ich suche sie kurz.", "Het nummer staat op het contract. Ik zoek het even op.", "The number is on the contract. Let me look it up.", "Le numéro est sur le contrat. Je le cherche.", "El número está en el contrato. Lo busco un momento."], ["a", "Kein Problem, nehmen Sie sich Zeit.", "Geen probleem, neem de tijd.", "No problem, take your time.", "Pas de problème, prenez votre temps.", "No hay problema, tómese su tiempo."], ["j", "Hier ist die Nummer: vierzehn sieben zwei.", "Hier is het nummer: veertien zeven twee.", "Here's the number: fourteen seven two.", "Voici le numéro : quatorze, sept, deux.", "Aquí está el número: catorce siete dos."], ["a", "Danke. Wann können Sie ein Techniker empfangen?", "Dank u. Wanneer bent u thuis voor een monteur?", "Thanks. When are you available for a technician?", "Merci. Quand êtes-vous disponible pour un technicien ?", "Gracias. ¿Cuándo puede recibir a un técnico?"], ["j", "Am Donnerstag zwischen acht und zwölf Uhr.", "Donderdag tussen acht en twaalf uur.", "On Thursday between eight and twelve.", "Jeudi entre huit heures et midi.", "El jueves entre las ocho y las doce."], ["a", "Gut, der Techniker kommt am Donnerstag.", "Goed, de monteur komt donderdag.", "Good, the technician will come on Thursday.", "Très bien, le technicien viendra jeudi.", "Bien, el técnico vendrá el jueves."], ["j", "Kostet das etwas?", "Kost dat iets?", "Does that cost anything?", "Ça coûte quelque chose ?", "¿Cuesta algo?"], ["a", "Nein, wenn es ein Problem bei uns ist, ist es kostenlos.", "Nee, als het aan onze kant ligt, is het gratis.", "No, if the problem is on our side, it's free.", "Non, si le problème vient de chez nous, c'est gratuit.", "No, si el problema es nuestro, es gratis."], ["j", "Und kann ich bis dahin mein Handy als Hotspot nutzen?", "Kan ik tot die tijd mijn telefoon als hotspot gebruiken?", "Until then, can I use my phone as a hotspot?", "En attendant, je peux utiliser mon téléphone comme point d'accès ?", "Mientras tanto, ¿puedo usar el móvil como punto de acceso?"], ["a", "Ja, das geht. Schalten Sie die Funktion in den Einstellungen ein.", "Ja, dat kan. Zet de functie aan in de instellingen.", "Yes, that works. Turn the feature on in the settings.", "Oui, c'est possible. Activez la fonction dans les paramètres.", "Sí, eso funciona. Actívelo en los ajustes."], ["j", "Danke, Sie haben mir sehr geholfen. Auf Wiederhören!", "Dank je, je hebt me erg geholpen. Tot ziens!", "Thanks, you've been very helpful. Goodbye!", "Merci, vous m'avez beaucoup aidé. Au revoir !", "Gracias, me ha ayudado mucho. ¡Adiós!"], ["a", "Gern geschehen. Einen schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]]}, {"n": 22, "t": "Werk en school: collega's en docent", "tt": {"de": "Arbeit und Schule: Kollegen und Lehrer", "nl": "Werk en school: collega's en docent", "en": "Work and school: colleagues and teacher", "fr": "Travail et école : collègues et professeur", "es": "Trabajo y escuela: compañeros y profesor"}, "r": [["j", "Guten Morgen, hast du kurz Zeit?", "Goedemorgen, heb je even tijd?", "Good morning, do you have a minute?", "Bonjour, tu as un moment ?", "Buenos días, ¿tienes un momento?"], ["a", "Ja, klar. Was gibt es?", "Ja, natuurlijk. Wat is er?", "Yes, sure. What's up?", "Oui, bien sûr. Qu'est-ce qu'il y a ?", "Sí, claro. ¿Qué pasa?"], ["j", "Ich wollte die Planung für nächste Woche besprechen.", "Ik wilde de planning voor volgende week bespreken.", "I wanted to discuss the schedule for next week.", "Je voulais parler du planning de la semaine prochaine.", "Quería hablar de la planificación de la semana que viene."], ["a", "Gut. Ich habe um elf Uhr Zeit.", "Goed. Ik heb om elf uur tijd.", "Good. I have time at eleven.", "Très bien. J'ai du temps à onze heures.", "Bien. Tengo tiempo a las once."], ["j", "Passt das für dich?", "Past dat voor jou?", "Does that work for you?", "Ça te convient ?", "¿Te viene bien?"], ["a", "Ja, perfekt. Bis dann.", "Ja, prima. Tot dan.", "Yes, perfect. See you then.", "Oui, parfait. À tout à l'heure.", "Sí, perfecto. Hasta entonces."], ["j", "Entschuldigung, ich bin heute zu spät. Der Bus hatte Verspätung.", "Sorry, ik ben vandaag te laat. De bus had vertraging.", "Sorry, I'm late today. The bus was delayed.", "Désolé, je suis en retard aujourd'hui. Le bus avait du retard.", "Perdona, llego tarde hoy. El autobús iba con retraso."], ["a", "Kein Problem. Kannst du das bitte im System eintragen?", "Geen probleem. Kun je dat even in het systeem zetten?", "No problem. Can you log it in the system, please?", "Pas de problème. Tu peux l'enregistrer dans le système ?", "No pasa nada. ¿Puedes registrarlo en el sistema?"], ["j", "Mache ich. Wer macht heute die Post?", "Doe ik. Wie doet vandaag de post?", "Will do. Who's doing the post today?", "Je le fais. Qui s'occupe du courrier aujourd'hui ?", "Lo hago. ¿Quién se encarga hoy del correo?"], ["a", "Das macht Lisa. Frag sie einfach.", "Dat doet Lisa. Vraag het haar gewoon.", "Lisa is. Just ask her.", "C'est Lisa. Demande-lui simplement.", "Lo hace Lisa. Pregúntale sin más."], ["j", "Okay, danke. Könntest du mir den Ordner geben?", "Oké, dank je. Kun je me de map geven?", "Okay, thanks. Could you give me the folder?", "D'accord, merci. Tu peux me donner le dossier ?", "Vale, gracias. ¿Me darías la carpeta?"], ["a", "Hier bitte. Die Unterlagen sind vollständig.", "Alsjeblieft. De stukken zijn compleet.", "Here you go. The documents are complete.", "Voilà. Les documents sont complets.", "Aquí tienes. Los documentos están completos."], ["j", "Super, danke dir. Wann ist die Besprechung?", "Super, bedankt. Wanneer is de vergadering?", "Great, thanks. When is the meeting?", "Super, merci. Quand est la réunion ?", "Genial, gracias. ¿Cuándo es la reunión?"], ["a", "Morgen um zehn Uhr im Konferenzraum.", "Morgen om tien uur in de vergaderzaal.", "Tomorrow at ten in the meeting room.", "Demain à dix heures dans la salle de réunion.", "Mañana a las diez en la sala de reuniones."], ["j", "Ich komme. Danke für die Info!", "Ik kom. Bedankt voor de info!", "I'll be there. Thanks for the info!", "J'y serai. Merci pour l'info !", "Allí estaré. ¡Gracias por la información!"], ["a", "Super. Bis morgen!", "Top. Tot morgen!", "Great. See you tomorrow!", "Super. À demain !", "Genial. ¡Hasta mañana!"]]}, {"n": 23, "t": "Wonen: buren en huur", "tt": {"de": "Wohnen: Nachbarn und Miete", "nl": "Wonen: buren en huur", "en": "Living: neighbours and rent", "fr": "Logement : voisins et loyer", "es": "Vivienda: vecinos y alquiler"}, "r": [["j", "Hallo, ich wohne nebenan. Ich wollte mich vorstellen.", "Hoi, ik woon hiernaast. Ik wilde me even voorstellen.", "Hi, I live next door. I wanted to introduce myself.", "Bonjour, j'habite à côté. Je voulais me présenter.", "Hola, vivo al lado. Quería presentarme."], ["a", "Oh, schön, Sie kennenzulernen. Ich bin Frau Krause.", "Oh, leuk je te ontmoeten. Ik ben mevrouw Krause.", "Oh, nice to meet you. I'm Mrs Krause.", "Oh, enchanté. Je suis Madame Krause.", "Qué bien conocerle. Soy la señora Krause."], ["j", "Ich bin Anna. Wir sind erst seit einer Woche hier.", "Ik ben Anna. We wonen hier pas een week.", "I'm Anna. We've only been here a week.", "Je suis Anna. Nous ne sommes là que depuis une semaine.", "Soy Anna. Solo llevamos aquí una semana."], ["a", "Herzlich willkommen! Wenn Sie etwas brauchen, sagen Sie Bescheid.", "Welkom! Als u iets nodig hebt, laat het gerust weten.", "Welcome! If you need anything, just let me know.", "Bienvenue ! Si vous avez besoin de quoi que ce soit, dites-le-moi.", "¡Bienvenidos! Si necesitan algo, avísenme."], ["j", "Danke. Wissen Sie, wann der Müll abgeholt wird?", "Dank u. Weet u wanneer de vuilnis wordt opgehaald?", "Thanks. Do you know when the rubbish is collected?", "Merci. Vous savez quand les poubelles sont ramassées ?", "Gracias. ¿Sabe cuándo recogen la basura?"], ["a", "Dienstags und freitags, am frühen Morgen.", "Dinsdag en vrijdag, vroeg in de ochtend.", "Tuesdays and Fridays, early in the morning.", "Le mardi et le vendredi, tôt le matin.", "Los martes y viernes, por la mañana temprano."], ["j", "Und wo sind die Fahrräder abgestellt?", "En waar kan ik de fietsen neerzetten?", "And where can bicycles be parked?", "Et où peut-on garer les vélos ?", "¿Y dónde se pueden aparcar las bicis?"], ["a", "Im Hof, hinter dem Haus.", "In de binnenplaats, achter het huis.", "In the courtyard, behind the house.", "Dans la cour, derrière la maison.", "En el patio, detrás de la casa."], ["j", "Gibt es Probleme mit Lärm? Ich habe einen Hund.", "Is er vaak last van lawaai? Ik heb een hond.", "Is there a problem with noise? I have a dog.", "Il y a des problèmes de bruit ? J'ai un chien.", "¿Hay problemas con el ruido? Tengo un perro."], ["a", "Nein, kein Problem. Wir haben auch Hunde im Haus.", "Nee, geen probleem. We hebben ook honden in het huis.", "No, no problem. We have dogs in the building too.", "Non, aucun problème. Nous avons aussi des chiens dans l'immeuble.", "No, ningún problema. También hay perros en el edificio."], ["j", "Ich bin mit der Heizung unsicher. Wie funktioniert sie?", "Ik weet niet zo goed hoe de verwarming werkt. Hoe werkt die?", "I'm not sure how the heating works. How does it work?", "Je ne sais pas très bien comment marche le chauffage. Comment ça marche ?", "No sé bien cómo funciona la calefacción. ¿Cómo funciona?"], ["a", "Am Thermostat im Flur. Ich zeige es Ihnen gern.", "Bij de thermostaat in de gang. Ik laat het u graag zien.", "On the thermostat in the hall. I'm happy to show you.", "Sur le thermostat dans le couloir. Je vous montre volontiers.", "En el termostato del pasillo. Con gusto se lo enseño."], ["j", "Das wäre super. Danke!", "Dat zou fijn zijn. Dank je!", "That would be great. Thanks!", "Ce serait super. Merci !", "Sería genial. ¡Gracias!"], ["a", "Gern. Wir sehen uns bestimmt wieder.", "Graag. We zien elkaar vast nog wel.", "Gladly. We'll see each other again for sure.", "Avec plaisir. On se reverra sûrement.", "Con gusto. Seguro que nos volvemos a ver."]]}, {"n": 24, "t": "Uitnodiging en verjaardag", "tt": {"de": "Einladung und Geburtstag", "nl": "Uitnodiging en verjaardag", "en": "Invitation and birthday", "fr": "Invitation et anniversaire", "es": "Invitación y cumpleaños"}, "r": [["j", "Hast du am Samstag Zeit? Ich feiere meinen Geburtstag.", "Heb je zaterdag tijd? Ik vier mijn verjaardag.", "Are you free on Saturday? I'm celebrating my birthday.", "Tu es libre samedi ? Je fête mon anniversaire.", "¿Tienes tiempo el sábado? Celebro mi cumpleaños."], ["a", "Ja, gern! Wann fängt es an?", "Ja, graag! Hoe laat begint het?", "Yes, I'd love to! What time does it start?", "Oui, avec plaisir ! À quelle heure ça commence ?", "¡Sí, encantado! ¿A qué hora empieza?"], ["j", "Um neunzehn Uhr, bei mir zu Hause.", "Om zeven uur, bij mij thuis.", "At seven in the evening, at my place.", "À dix-neuf heures, chez moi.", "A las siete de la tarde, en mi casa."], ["a", "Super! Soll ich etwas mitbringen?", "Super! Moet ik iets meenemen?", "Great! Should I bring something?", "Super ! Je dois apporter quelque chose ?", "¡Genial! ¿Tengo que llevar algo?"], ["j", "Ein paar Getränke wären toll. Ich mache das Essen.", "Een paar drankjes zou fijn zijn. Ik maak het eten.", "A few drinks would be great. I'm making the food.", "Quelques boissons seraient parfaites. Je m'occupe de la nourriture.", "Algunas bebidas estarían bien. Yo me encargo de la comida."], ["a", "Alles klar. Ich bringe Wein mit.", "Goed. Ik neem wijn mee.", "Got it. I'll bring some wine.", "D'accord. J'apporte du vin.", "Vale. Llevaré vino."], ["j", "Danke! Ich freue mich, dass du kommst.", "Dank je! Ik ben blij dat je komt.", "Thanks! I'm glad you're coming.", "Merci ! Je suis contente que tu viennes.", "¡Gracias! Me alegra que vengas."], ["a", "Herzlichen Glückwunsch nachträglich! Ich freue mich auch.", "Alvast gefeliciteerd! Ik kijk ernaar uit.", "Happy birthday in advance! I'm looking forward to it.", "Joyeux anniversaire d'avance ! J'ai hâte.", "¡Feliz cumpleaños por adelantado! Tengo ganas."], ["j", "Kannst du noch Freunde mitbringen?", "Mag je nog vrienden meenemen?", "Can you bring some friends too?", "Tu peux amener des amis ?", "¿Puedes traer amigos también?"], ["a", "Ja, klar. Wie viele Leute kommen ungefähr?", "Ja, natuurlijk. Hoeveel mensen komen er ongeveer?", "Yes, of course. How many people are coming roughly?", "Oui, bien sûr. Il y aura environ combien de personnes ?", "Sí, claro. ¿Más o menos cuántas personas vendrán?"], ["j", "Etwa zehn Leute. Das Haus ist nicht sehr groß.", "Ongeveer tien mensen. Het huis is niet zo groot.", "About ten people. The house isn't very big.", "Une dizaine de personnes. La maison n'est pas très grande.", "Unas diez personas. La casa no es muy grande."], ["a", "Kein Problem, wir kommen pünktlich.", "Geen probleem, we komen op tijd.", "No problem, we'll be on time.", "Pas de problème, nous arriverons à l'heure.", "No hay problema, llegaremos puntuales."], ["j", "Super, bis Samstag!", "Super, tot zaterdag!", "Great, see you Saturday!", "Super, à samedi !", "¡Genial, hasta el sábado!"], ["a", "Bis Samstag! Schönen Abend noch.", "Tot zaterdag! Fijne avond nog.", "See you Saturday! Have a good evening.", "À samedi ! Bonne soirée.", "¡Hasta el sábado! Que tengas buena tarde."]]}, {"n": 25, "t": "Weer en kleine praatjes", "tt": {"de": "Wetter und Smalltalk", "nl": "Weer en kleine praatjes", "en": "Weather and small talk", "fr": "Météo et petites conversations", "es": "El tiempo y charlas cortas"}, "r": [["j", "Was für ein schönes Wetter heute!", "Wat een mooi weer vandaag!", "What lovely weather today!", "Quel beau temps aujourd'hui !", "¡Qué buen tiempo hace hoy!"], ["a", "Ja, endlich mal Sonne!", "Ja, eindelijk zon!", "Yes, finally some sun!", "Oui, enfin du soleil !", "¡Sí, por fin sol!"], ["j", "Ist es morgen auch so warm?", "Wordt het morgen ook zo warm?", "Will it be this warm tomorrow too?", "Il fera aussi chaud demain ?", "¿Mañana también hará este calor?"], ["a", "Ich glaube, es wird kälter und es regnet.", "Ik denk dat het kouder wordt en gaat regenen.", "I think it'll get colder and it'll rain.", "Je crois qu'il fera plus froid et qu'il pleuvra.", "Creo que hará más frío y lloverá."], ["j", "Oh, dann nehme ich lieber einen Regenschirm mit.", "Oh, dan neem ik beter een paraplu mee.", "Oh, then I'd better take an umbrella.", "Oh, alors je ferais mieux de prendre un parapluie.", "Vaya, entonces mejor me llevo un paraguas."], ["a", "Gute Idee. Haben Sie das Wochenende schon geplant?", "Goed idee. Heb je het weekend al gepland?", "Good idea. Have you planned your weekend yet?", "Bonne idée. Tu as déjà prévu ton week-end ?", "Buena idea. ¿Ya tienes planes para el fin de semana?"], ["j", "Noch nicht. Vielleicht ein bisschen Sport, du?", "Nog niet. Misschien een beetje sporten, jij?", "Not yet. Maybe some sport. What about you?", "Pas encore. Peut-être un peu de sport, et toi ?", "Todavía no. Quizás hacer deporte, ¿y tú?"], ["a", "Ich gehe joggen. Das ist für mich der beste Start.", "Ik ga hardlopen. Dat is voor mij de beste start.", "I go jogging. That's the best start for me.", "Je fais du jogging. C'est le meilleur départ pour moi.", "Yo salgo a correr. Para mí es el mejor comienzo."], ["j", "Klingt gesund! Wo läufst du gern?", "Klinkt gezond! Waar loop je graag?", "Sounds healthy! Where do you like to run?", "Ça a l'air sain ! Tu aimes courir où ?", "¡Suena sano! ¿Dónde te gusta correr?"], ["a", "Im Park am Fluss. Der ist sehr schön.", "In het park langs de rivier. Dat is erg mooi.", "In the park by the river. It's very nice.", "Dans le parc au bord de la rivière. C'est très joli.", "En el parque junto al río. Es muy bonito."], ["j", "Den kenne ich noch nicht. Danke für den Tipp!", "Die ken ik nog niet. Bedankt voor de tip!", "I don't know it yet. Thanks for the tip!", "Je ne le connais pas encore. Merci pour le conseil !", "Todavía no lo conozco. ¡Gracias por el consejo!"], ["a", "Gern geschehen. Viel Spaß!", "Graag gedaan. Veel plezier!", "You're welcome. Have fun!", "Avec plaisir. Amuse-toi bien !", "De nada. ¡Que lo disfrutes!"], ["j", "Danke, dir auch einen schönen Tag!", "Dank je, jij ook een fijne dag!", "Thanks, have a nice day too!", "Merci, bonne journée à toi aussi !", "¡Gracias, que tengas buen día tú también!"], ["a", "Tschüss! Bis bald.", "Doei! Tot snel.", "Bye! See you soon.", "Salut ! À bientôt.", "¡Adiós! Hasta pronto."]]}];
